library;

/// Which `app_config/{doc}` a setting is read from — see DECISIONS.md ADR-023
/// (placement rule: a setting lives in the most restrictive doc that still
/// contains every one of its readers).
enum ConfigDoc { critical, client, server }

ConfigDoc configDocFromString(String s) => switch (s) {
  'critical' => ConfigDoc.critical,
  'client' => ConfigDoc.client,
  'server' => ConfigDoc.server,
  _ => throw ArgumentError('Unknown ConfigDoc: $s'),
};

/// One schema-declared field descriptor. Drives the schema-generated admin
/// config editor (Faz C) and the read-side bounds clamp (DECISIONS.md ADR-023).
/// Carries no `default` — see kConfigDefaults in app_config_defaults.g.dart.
class ConfigField {
  final String key;
  final String type;
  final ConfigDoc doc;
  final String group;
  final String label;
  final String description;
  final String impact;
  final bool sensitive;
  final num? min;
  final num? max;
  final List<String>? enumValues;

  const ConfigField({
    required this.key,
    required this.type,
    required this.doc,
    required this.group,
    required this.label,
    required this.description,
    required this.impact,
    this.sensitive = false,
    this.min,
    this.max,
    this.enumValues,
  });
}

const List<ConfigField> kConfigSchema = [
  ConfigField(key: 'ai.allowed_models', type: 'string_list', doc: ConfigDoc.server, group: 'ai_server', label: 'İzin verilen model listesi', description: 'Amacı, adminlerin yeni bir modeli koda dokunmadan onaylı model listesine ekleyebilmesiydi. Ancak bu alan bugün hem uygulamada hem sunucuda ÖLÜ durumdadır: isteklerde gerçekte kullanılan model bu listeye karşı hiç denetlenmez. Sunucudaki gerçek (ve tek) model kısıtlaması koda gömülü, admin panelinden görünmeyen ayrı bir sabit listeyle yapılır; o listeyi değiştirmek hâlâ bir kod değişikliği ve redeploy gerektirir.', impact: 'Bu alanı değiştirmenin uygulamada veya sunucuda şu an gözlemlenebilir hiçbir etkisi yoktur — gerçek model kısıtlaması geliştirici tarafından koda gömülü, bu panelden erişilemeyen bir listeyle yapılmaya devam etmektedir.', sensitive: true),
  ConfigField(key: 'ai.free_daily_limit', type: 'int', doc: ConfigDoc.client, group: 'ai', label: 'Ücretsiz günlük AI hakkı', description: 'Ücretsiz (premium olmayan) bir kullanıcının bir günde yapabileceği AI üretimi (öneri, tarif, sohbet vb.) sayısının üst sınırıdır. Bu sınır sunucudaki AI proxy\'sinde fiilen uygulanır; sınıra ulaşan kullanıcının isteği reddedilir ve uygulama premium/kredi ekranını gösterir. Uygulama içindeki \'bugün kaç hakkın kaldı\' rozeti ise bu değeri değil koddaki sabit bir sayıyı gösterir, bu yüzden buradan yapılan bir değişiklik rozet metnine hemen yansımayabilir.', impact: 'Yükseltmek ücretsiz kullanıcı başına AI maliyetini doğrudan artırır, düşürmek ise meşru kullanıcıları daha erken kilitleyerek premium\'a yönlendirir.', sensitive: true, min: 0, max: 100),
  ConfigField(key: 'ai.max_messages', type: 'int', doc: ConfigDoc.server, group: 'ai_server', label: 'Maksimum mesaj sayısı (sohbet)', description: 'Bir sohbet isteğinde AI proxy\'ye tek seferde gönderilen mesaj dizisinde en fazla kaç mesaj (kullanıcı+asistan geçmişi) kabul edileceğini belirler. Bu sınırı aşan istek sunucu tarafından doğrudan reddedilir, OpenRouter\'a hiç gönderilmez. Amacı, aşırı uzun bir sohbet geçmişinin tek istekte gereğinden fazla token ve maliyete yol açmasını önlemektir.', impact: 'Yükseltmek uzun sohbet geçmişlerine izin vererek maliyeti ve gecikmeyi artırır, düşürmek ise eski mesajların bağlamdan düşüp sohbetin tutarlılığını kaybetmesine yol açabilir.', min: 1, max: 200),
  ConfigField(key: 'ai.max_retries', type: 'int', doc: ConfigDoc.client, group: 'ai', label: 'AI çağrısı yeniden deneme sayısı', description: 'Bir AI isteği geçici bir ağ/sunucu hatası yüzünden başarısız olduğunda uygulamanın aynı isteği kaç kez daha deneyeceğini belirler. Yalnızca uygulama (istemci) tarafında çalışır, sunucuda bir karşılığı yoktur. Deneme sayısı tükendiğinde kullanıcıya hata gösterilir.', impact: 'Yükseltmek geçici hatalara karşı dayanıklılığı artırır ama en kötü durumda kullanıcının hata görene kadar beklediği süreyi uzatır; düşürmek bu süreyi kısaltır ama aslında bir sonraki denemede başarılı olabilecek istekleri erken pes ettirebilir.', min: 0, max: 10),
  ConfigField(key: 'ai.max_tokens', type: 'int', doc: ConfigDoc.server, group: 'ai_server', label: 'Maksimum çıktı token (varsayılan)', description: 'Sunucunun AI modelinden isteyeceği yanıtın en fazla kaç token uzunluğunda olacağının varsayılan üst sınırıdır; sorguya özel bir değer (ai.max_tokens_by_type) tanımlı değilse bu sınır kullanılır. Yanıt uzunluğu arttıkça hem yanıt süresi hem de ücretli modellerde maliyet artar. Ne girilirse girilsin sunucu bu değeri her zaman 32000 ile sınırlar; bu tavanın üzerine çıkılamaz.', impact: 'Yükseltmek uzun yanıt gerektiren isteklerin (örn. haftalık plan) yarıda kesilmesini önler ama ücretli modellerde maliyeti artırır; düşürmek maliyeti azaltır ama uzun yanıtların yarıda kesilme riskini yükseltir.', min: 256, max: 32000),
  ConfigField(key: 'ai.max_tokens_by_type', type: 'map<string,int>', doc: ConfigDoc.server, group: 'ai_server', label: 'Sorgu tipine göre maksimum token', description: 'ai.max_tokens\'ın sorgu türüne göre özelleştirilmiş halidir — bir tür için burada değer tanımlıysa genel ai.max_tokens yerine bu değer kullanılır. Böylece örneğin uzun bir yemek planı için yüksek, kısa bir sohbet yanıtı için düşük bir token sınırı ayrı ayrı tanımlanabilir. Burada girilen değerler de sunucu tarafından her zaman 32000 tavanına göre sınırlanır.', impact: 'Bir türe çok yüksek değer vermek o türün maliyetini artırır, çok düşük değer vermek ise o türdeki yanıtların yarıda kesilme riskini yükseltir.'),
  ConfigField(key: 'ai.max_total_chars', type: 'int', doc: ConfigDoc.server, group: 'ai_server', label: 'Maksimum toplam karakter (payload)', description: 'Bir AI isteğindeki tüm mesajların (JSON olarak serileştirilmiş haliyle) toplam karakter uzunluğu için üst sınırdır. Bu sınırı aşan istekler sunucu tarafından reddedilir ve OpenRouter\'a hiç gönderilmez. ai.max_messages\'a ek bir koruma katmanıdır — az sayıda ama çok uzun mesajla oluşabilecek aynı aşırı-payload riskini engeller.', impact: 'Yükseltmek daha uzun içeriklere (örn. uzun profil/tarif metinleri) izin verir ama tek istekteki token maliyetini artırır, düşürmek maliyeti sınırlar ama meşru uzun isteklerin reddedilmesine yol açabilir.', min: 1000, max: 200000),
  ConfigField(key: 'ai.model_by_type', type: 'map<string,string>', doc: ConfigDoc.server, group: 'ai_server', label: 'Sorgu tipine göre model', description: 'Belirli sorgu türleri için (örn. haftalık yemek planı, tarif üretimi, koç raporu) ai.text_model\'den farklı, türe özel bir model atanmasını sağlar; burada tanımlanmayan bir tür ai.text_model\'i kullanmaya devam eder. Bu alan yalnızca sunucu tarafından okunur (AI proxy ve koç raporu üretimi) — uygulamanın kendisinde bu eşlemeyi kullanan bir ekran yoktur. Örneğin maliyetli/karmaşık bir türe daha güçlü, sık kullanılan bir türe daha ucuz bir model atanabilir.', impact: 'Maliyetli bir sorgu türüne pahalı bir model atamak o tür için toplam AI maliyetini belirgin biçimde artırır; bu eşleme de onaylı bir model listesine karşı denetlenmeden doğrudan kullanılır.', sensitive: true),
  ConfigField(key: 'ai.model_pricing', type: 'map<string,object>', doc: ConfigDoc.server, group: 'ai_server', label: 'Model fiyatlandırması (USD/1M token)', description: 'Uygulamanın kullandığı AI modellerinin OpenRouter üzerindeki girdi/çıktı token\'ı başına USD maliyetini (1 milyon token başına) tanımlayan tablodur. Kullanıcıya hiçbir şekilde gösterilmez; yalnızca sunucunun her isteğin gerçek token kullanımından maliyet hesaplayıp admin maliyet panosuna (cost dashboard) yazması için kullandığı dahili bir veridir. Tabloda yer almayan bir model otomatik olarak \'fiyatsız\' işaretlenip maliyeti 0 sayılır — panoda \'fiyatlandırma eksik\' olarak görünür, gerçek maliyetin sıfır olduğu anlamına gelmez.', impact: 'Buradaki birim fiyatları gerçeğinden düşük girmek maliyet panosunun gerçek harcamanın altında rakamlar göstermesine yol açar; yeni eklenen bir modeli bu tabloya eklemeyi unutmak o modelin maliyetinin panoda sıfır/fiyatsız görünmesine neden olur.', sensitive: true),
  ConfigField(key: 'ai.premium_daily_limit', type: 'int', doc: ConfigDoc.client, group: 'ai', label: 'Premium günlük AI hakkı', description: 'Premium (ücretli) bir kullanıcının bir günde yapabileceği AI üretimi sayısının üst sınırıdır; ai.free_daily_limit ile aynı mekanizmayla sunucudaki AI proxy\'sinde fiilen uygulanır. Sınıra ulaşan premium kullanıcının isteği de reddedilir. Uygulama içindeki kredi rozeti bu değeri değil koddaki sabit sayıyı gösterdiğinden, buradaki bir değişiklik rozet metnine hemen yansımayabilir.', impact: 'Yükseltmek premium kullanıcı başına AI maliyetini doğrudan artırır, düşürmek ise ücret ödeyen kullanıcıları günün ilerleyen saatlerinde kilitleyerek memnuniyetsizliğe yol açabilir.', sensitive: true, min: 0, max: 500),
  ConfigField(key: 'ai.rate_max_in_window', type: 'int', doc: ConfigDoc.server, group: 'ai_server', label: 'Pencere başına maksimum çağrı', description: 'ai.rate_window_ms ile tanımlanan pencere içinde bir kullanıcının en fazla kaç AI isteği yapabileceğini belirler; günlük toplam haktan (ai.free_daily_limit/ai.premium_daily_limit) bağımsız, kısa vadeli bir \'ani patlama\' sınırıdır. Bu sınırı aşan istekler günlük hakka dokunulmadan doğrudan reddedilir.', impact: 'Yükseltmek kısa sürede daha fazla art arda isteğe izin vererek script/otomasyon kaynaklı kötüye kullanım riskini artırır, düşürmek ise meşru bir kullanıcının kısa sürede birkaç kez yeniden deneme yapmasını (örn. beğenmediği bir öneriyi hemen yenilemesini) engelleyebilir.', sensitive: true, min: 1, max: 1000),
  ConfigField(key: 'ai.rate_window_ms', type: 'int', doc: ConfigDoc.server, group: 'ai_server', label: 'AI hız sınırı penceresi (ms)', description: 'Günlük AI hakkından bağımsız olarak, bir kullanıcının kaç milisaniyelik bir pencere içinde sınırlı sayıda istek yapabileceğini belirler (ai.rate_max_in_window ile birlikte çalışır). Amacı, günlük hakkı dolmamış bir kullanıcının kısa sürede art arda çok sayıda istek göndermesini (script/otomasyon, hatalı tekrar tıklama vb.) engellemektir. Pencere dolduğunda sayaç sıfırlanır.', impact: 'Bu süreyi kısaltmak (aynı çağrı sayısında) daha hızlı art arda istek yapılmasına izin vererek kötüye kullanım ve OpenRouter\'ın paylaşılan anahtarının aşırı yüklenmesi riskini artırır, uzatmak ise meşru ama hızlı ardışık kullanımı daha sık geçici olarak engelleyebilir.', sensitive: true, min: 1000, max: 3600000),
  ConfigField(key: 'ai.retry_delay_s', type: 'int', doc: ConfigDoc.client, group: 'ai', label: 'Yeniden deneme gecikmesi (sn)', description: 'Başarısız bir AI isteğinden sonra uygulamanın bir sonraki denemeyi kaç saniye bekleyerek yapacağını belirler; bu süre her denemede deneme sayısıyla çarpılarak uygulanır, yani denemeler ilerledikçe bekleme de uzar. Yalnızca uygulama (istemci) tarafında çalışır. ai.max_retries ile birlikte, bir hatadan sonra toplam ne kadar beklenip yeniden denendiğini belirler.', impact: 'Süreyi kısaltmak geçici bir hatanın hemen art arda tekrar denenmesine yol açar, uzatmak ise kullanıcının bir hatadan kurtulup sonuç görene kadar bekleme süresini artırır.', min: 0, max: 30),
  ConfigField(key: 'ai.temperature', type: 'double', doc: ConfigDoc.server, group: 'ai_server', label: 'Model sıcaklığı', description: 'AI modelinin yanıt üretirken ne kadar \'yaratıcı/çeşitli\' (yüksek değer) ya da \'tutarlı/öngörülebilir\' (düşük değer) davranacağını belirleyen model sıcaklığıdır. Tarif/plan üretimi gibi yapılandırılmış (JSON) çıktılarda düşük bir değer talimatlara daha sadık sonuçlar verir; yüksek bir değer daha çeşitli ama bazen biçim hatası içeren sonuçlara yol açabilir. Sunucu bu değeri her zaman 0 ile 1 arasına sıkıştırır.', impact: 'Değeri çok yükseltmek AI yanıtlarının beklenen JSON formatına uymama ve ayrıştırma hatası verme ihtimalini artırır, çok düşürmek ise yanıtları tekdüze hale getirir.', min: 0, max: 1),
  ConfigField(key: 'ai.text_model', type: 'string', doc: ConfigDoc.client, group: 'ai', label: 'Metin modeli (override)', description: 'Uygulamanın metin tabanlı AI isteklerinde (plan/tarif üretimi, sohbet, öneriler vb.) hangi modelin kullanılacağını belirtir. Boş bırakıldığında hem uygulama hem sunucu kendi dahili varsayılan modelini (bugün openai/gpt-4o-mini) kullanmaya devam eder; burada bir model adı girildiğinde tüm bu istekler onun yerine bu modeli kullanır. Hem telefon uygulaması hem sunucudaki AI proxy aynı değeri okuduğu için değişiklik anında her iki tarafta da etkili olur.', impact: 'Buraya yazılan model adı onaylı bir listeye karşı denetlenmeden doğrudan kullanılır, bu yüzden hatalı ya da pahalı bir model adı girmek tüm kullanıcıların AI isteklerini o modele ve maliyetine yönlendirir.'),
  ConfigField(key: 'ai.timeout_s', type: 'int', doc: ConfigDoc.client, group: 'ai', label: 'AI istek zaman aşımı (sn)', description: 'Uygulamanın bir AI isteğinin yanıtını en fazla kaç saniye bekleyeceğini belirler. Süre dolduğunda istek başarısız sayılır ve yeniden deneme mekanizması (ai.max_retries/ai.retry_delay_s) devreye girer. Haftalık yemek planı gibi büyük/karmaşık isteklerde yavaş modeller 45 saniyeden uzun sürebildiğinden, bu değer çok düşük tutulursa aslında başarılı olabilecek istekler zaman aşımına uğrayabilir.', impact: 'Süreyi kısaltmak yavaş modellerde tamamlanabilecek istekleri gereksiz yere başarısız gösterir, uzatmak ise kullanıcıyı yanıt için ekranda daha uzun süre bekletir.', min: 10, max: 300),
  ConfigField(key: 'ai.vision_model', type: 'string', doc: ConfigDoc.client, group: 'ai', label: 'Görsel modeli (override)', description: 'Yemek fotoğrafı tarama gibi görsel analiz isteklerinde hangi görsel (vision) AI modelinin kullanılacağını belirtir; ai.text_model ile aynı mekanizmayı kullanır, sadece fotoğraf tabanlı istekler için. Boş bırakıldığında hem uygulama hem sunucu kendi varsayılan görsel modelini (bugün ücretsiz bir Llama vision modeli) kullanmaya devam eder. Burada bir model adı girildiğinde fotoğraf analizi isteklerinin tamamı onun yerine bu modeli kullanır.', impact: 'Buraya yazılan model adı da onay listesine karşı denetlenmeden doğrudan kullanılır, bu yüzden ücretli/pahalı bir görsel model girmek yemek fotoğrafı taramasının maliyetini belirgin biçimde artırabilir.'),
  ConfigField(key: 'announcement.cta_url', type: 'string', doc: ConfigDoc.critical, group: 'announcement', label: 'Duyuru CTA URL', description: 'Doldurulduğunda tüm duyuru şeridini tıklanabilir yapar ve kullanıcı şeride dokunduğunda bu adresi açar; ayrıca şeride küçük bir ok ikonu eklenir. Boş bırakılırsa şerit yalnızca bilgilendirme amaçlı kalır, tıklanamaz ve ok ikonu görünmez.', impact: 'Düşük risk — yalnızca şeridin tıklanabilir olup olmadığını ve yönlendirdiği adresi etkiler.'),
  ConfigField(key: 'announcement.dismissible', type: 'bool', doc: ConfigDoc.critical, group: 'announcement', label: 'Kapatılabilir', description: 'Duyuru şeridinde kapatma (X) ikonunun gösterilip gösterilmeyeceğini belirler. Kapatılabilir olduğunda kullanıcı şeridi bir kez kapattığında cihazında hatırlanır ve tekrar gösterilmez. Kapatılamaz yapıldığında X ikonu hiç görünmez ve önceki kapatma kayıtları da dikkate alınmaz — yani duyuru, enabled açık kaldığı sürece her açılışta yeniden görünür.', impact: 'Kapatılamaz yapmak duyuruyu kullanıcılar için gizlenemez hale getirir; kapatılabilir yapmak her kullanıcının şeridi bir kez kapatıp bir daha görmemesine izin verir.'),
  ConfigField(key: 'announcement.enabled', type: 'bool', doc: ConfigDoc.critical, group: 'announcement', label: 'Duyuru aktif', description: 'Uygulamanın üst kısmında görünen duyuru şeridinin görünür olup olmadığını belirler. Kapalıyken şerit hiçbir ekranda görünmez; açıldığında, mesaj metni boş olmadığı sürece, henüz kapatmamış tüm kullanıcılara görünür hale gelir. Bu alan anlık izlenen bir belgede tutulduğundan, değişiklik uygulama yeniden başlatılmadan açık oturumlara da hemen yansır.', impact: 'Açmak duyuruyu anında tüm kullanıcılara gösterir, kapatmak anında gizler — düşük risk, yalnızca bilgilendirme şeridini etkiler.'),
  ConfigField(key: 'announcement.id', type: 'string', doc: ConfigDoc.critical, group: 'announcement', label: 'Duyuru ID (dismiss tracking)', description: 'Duyurunun \'kapatıldı\' bilgisini cihaz üzerinde hatırlamak için kullanılan bir kimliktir; kullanıcı arayüzünde görünmez. Bir kullanıcı duyuruyu kapattığında bu kimlik cihazında saklanır ve aynı kimlikle gelen duyuru bir daha gösterilmez. Mesaj metnini güncelleyip aynı duyuruyu daha önce kapatmış kullanıcılara yeniden göstermek istendiğinde bu kimliğin de değiştirilmesi gerekir; değiştirilmezse önceden kapatmış kullanıcılar güncellenmiş mesajı görmez.', impact: 'Kimliği değiştirmek, bu duyuruyu daha önce kapatmış olan herkeste şeridi yeniden gösterir; aynı kimlikle küçük bir metin düzeltmesi yapmak kapatma kaydını korur.'),
  ConfigField(key: 'announcement.message', type: 'map<string,string>', doc: ConfigDoc.critical, group: 'announcement', label: 'Duyuru mesajı (en/tr)', description: 'Duyuru şeridi içinde gösterilen İngilizce/Türkçe metindir. Kullanıcının uygulama diline göre uygun metin gösterilir; geçerli dil için metin boşsa, announcement.enabled açık olsa bile şerit hiç görünmez.', impact: 'Metni boşaltmak, enabled açık kalsa dahi duyuruyu fiilen gizler; düşük risk, yalnızca görüntülenen yazıyı etkiler.'),
  ConfigField(key: 'announcement.type', type: 'enum', doc: ConfigDoc.critical, group: 'announcement', label: 'Duyuru tipi', description: 'Duyuru şeridinin rengini ve ikonunu belirler: \'warning\' turuncu/uyarı ikonu, \'success\' yeşil/onay ikonu ile gösterilir. \'info\' ve \'promo\' seçenekleri ise şu anda aynı mavi/megafon görünümünü kullanır — arayüzde \'promo\' için henüz ayrı bir görsel stil tanımlanmamıştır. Bu alan yalnızca görünümü etkiler, duyurunun gösterilip gösterilmeyeceğini değiştirmez.', impact: 'Düşük risk — yalnızca şeridin rengi/ikonu değişir; \'promo\' seçmek görsel olarak \'info\' ile aynı sonucu verir.', enumValues: <String>['info', 'warning', 'success', 'promo']),
  ConfigField(key: 'broadcast.max_recipients', type: 'int', doc: ConfigDoc.server, group: 'ops_caps', label: 'Yayın (broadcast) maksimum alıcı sayısı', description: 'Bir yayının (broadcast) tek seferde en fazla kaç kullanıcıya gönderilebileceğini belirler. "Tüm kullanıcılar", "koçlar" veya "salon sahipleri" gibi geniş bir kitleye gönderilen bir yayın, eşleşen kullanıcı sayısı bu sınırı aşarsa, sınırın dışında kalan kullanıcılara HİÇBİR bildirim gitmez ve bu durum bugün panelde herhangi bir uyarıyla belirtilmez — sessizce kırpılır. Bire bir (belirli bir kullanıcıya) gönderilen yayınları etkilemez.', impact: 'Yükseltmek gerçekte kaç kullanıcıya ulaşılabileceğini artırır ama tek seferde gönderilen push bildirimi sayısını da artırır; bu sınırı aşan bir kitleye yayın yapmak, sınırın üzerindeki kullanıcıların yayını hiç görmemesine yol açar.', sensitive: true, min: 1, max: 5000),
  ConfigField(key: 'client.check_in_radius_m', type: 'int', doc: ConfigDoc.client, group: 'client_misc', label: 'Salon check-in yarıçapı (m)', description: 'Bir üyenin salonda check-in yapabilmesi için GPS konumunun salonun konumuna en fazla kaç metre yakın olması gerektiğini belirleyen varsayılan/başlangıç yarıçapıdır. Her salon sahibi kendi kurulum ekranından salonu için bu yarıçapı ayrıca özelleştirebilir (50-300 metre arasında); bu değer o ayarın ilk açıldığındaki varsayılanını temsil eder. Tolerans arttıkça salon dışından da check-in yapılabilir hale gelir, azaldıkça bina içi GPS sapması yüzünden gerçek üyeler check-in yapamayabilir.', impact: 'Yarıçapı büyütmek salon dışından erken/sahte check-in riskini artırır, küçültmek ise GPS\'in bina içinde tam doğru çalışmadığı durumlarda gerçek üyelerin check-in yapamamasına yol açabilir.', min: 10, max: 1000),
  ConfigField(key: 'client.max_dishes_per_prompt', type: 'int', doc: ConfigDoc.client, group: 'client_misc', label: 'Prompt başına maksimum yemek sayısı', description: 'Haftalık yemek planı veya şablon önerisi üretilirken AI\'ya tek seferde gönderilecek aday yemek havuzunun en fazla kaç yemekle sınırlı tutulacağını belirler. Katalog bu sayıyı aştığında yemekler öğün türüne (kahvaltı/öğle/akşam/atıştırmalık) göre dengeli şekilde seçilir, böylece tek bir öğün türü tamamen dışarıda kalmaz. Amacı, katalog büyüdükçe her AI isteğinin token miktarının (ve maliyetinin) sınırsız artmasını önlemektir.', impact: 'Değeri düşürmek AI isteğinin maliyetini azaltır ama plan önerilerinin çeşitliliğini kısıtlar, yükseltmek çeşitliliği artırır ama her plan üretiminin token maliyetini yükseltir.', min: 20, max: 500),
  ConfigField(key: 'client.min_age_years', type: 'int', doc: ConfigDoc.critical, group: 'compliance', label: 'Minimum yaş (KVKK/GDPR)', description: 'Uygulamaya kayıt olabilmek için gereken minimum yaşı belirler; sağlık verisi işlendiği için KVKK/GDPR kapsamında ihtiyatlı bir eşik seçilmiştir. Bu kontrol hesap oluşturmadan ÖNCE, kayıt akışındaki doğum tarihi adımında yapılır — girilen tarih bu yaşın altına düşüyorsa devam edilemez. Hesap açılmadan önce okunabilmesi gerektiğinden herkese açık (oturum gerektirmeyen) bir belgede tutulur.', impact: 'Bu yaşı düşürmek hukuki/uyumluluk riski doğurabileceğinden hukuk onayı olmadan değiştirilmemelidir, yükseltmek ise bu yaş aralığındaki kullanıcıların kayıt olmasını engeller.', sensitive: true, min: 13, max: 21),
  ConfigField(key: 'client.referral_pending_code_ttl_days', type: 'int', doc: ConfigDoc.critical, group: 'referral', label: 'Bekleyen referans kodu TTL (gün)', description: 'Bir kullanıcı henüz hesabı yokken bir davet linkine (deep link) tıkladığında, o referans kodunun cihazda en fazla kaç gün \'bekleyen kod\' olarak saklanacağını belirler. Kullanıcı bu süre içinde kayıt olup onboarding\'i tamamlarsa kod otomatik uygulanır; süre dolmuşsa kod sessizce silinir ve kayıt sırasında artık otomatik eşleştirilmez. Hesap açılmadan önce okunabilmesi gerektiğinden herkese açık bir belgede tutulur.', impact: 'Süreyi kısaltmak, linke tıklayıp kaydolmayı geciktiren kullanıcılarda referans ödülünün/atfının sessizce kaybolmasına yol açar; uzatmak bu kaybı azaltır ve düşük risklidir çünkü gerçek doğrulama zaten sunucu tarafında ayrıca yapılır.', min: 1, max: 30),
  ConfigField(key: 'client.weekly_meal_plan_expiry_days', type: 'int', doc: ConfigDoc.client, group: 'client_misc', label: 'Haftalık plan geçerlilik süresi (gün)', description: 'AI tarafından üretilen haftalık yemek planının kaç gün geçerli sayılacağını belirler; bu süre dolana kadar uygulama var olan planı yeniden kullanır, süre dolunca kullanıcı için yeni bir AI isteğiyle yeni bir plan üretilir. Böylece bu değer, her kullanıcı için ne sıklıkla yeni bir AI çağrısı (ve maliyeti) yapılacağını dolaylı olarak belirler.', impact: 'Süreyi kısaltmak planları daha güncel tutar ama AI maliyetini ve kullanım hakkı tüketimini artırır, uzatmak maliyeti azaltır ama kullanıcı profilini güncellese bile eski planın daha uzun süre gösterilmesine yol açar.', min: 1, max: 30),
  ConfigField(key: 'cost.pricing', type: 'object', doc: ConfigDoc.server, group: 'economy', label: 'Maliyet/gelir varsayımları (admin cost dashboard)', description: 'Admin paneline özel \'maliyet ve kâr tahmini\' panosunu besleyen, elle girilmiş birim fiyat ve varsayımlar bütünüdür: Firestore okuma/yazma/silme/depolama, Cloud Storage, Cloud Functions çağrısı ve Cloud Vision taraması için GCP/Firebase birim fiyatları; AI (OpenRouter) çağrı başına maliyet varsayımı; premium abonelik ve AI kredi paketi fiyatları ile mağaza komisyon oranı gibi gelir varsayımlarını içerir. Bu değerler gerçek Firebase faturalandırma verisi değildir — uygulama gerçek faturalama bilgisine erişemediğinden, kullanım sayılarına (kullanıcı, doküman, AI çağrısı vb.) bu birim fiyatlar uygulanarak elde edilen bir tahmindir ve yalnızca yön gösterici olarak değerlendirilmelidir.', impact: 'Buradaki sayıları gerçek fiyat ve maliyetlerinizden farklı girmek yalnızca admin panelindeki maliyet, gelir ve kâr marjı tahminlerinin gerçek faturadan sapmasına yol açar; uygulamanın işleyişini veya kullanıcıları etkilemez.', sensitive: true),
  ConfigField(key: 'economy.gym_commission_try', type: 'map<string,double>', doc: ConfigDoc.server, group: 'economy', label: 'Salon komisyonu (₺, ürün başına)', description: 'Bir kullanıcı bir salonun davet kodu veya QR\'ı üzerinden gelip premium abonelik satın aldığında, o salonun sahibine ürün başına ödenecek sabit TL komisyonu belirler (varsayılan: aylık pakette 15 TL, yıllık pakette 120 TL). Anahtarlar mağaza ürün kimlikleridir ve \'Ürün kataloğu\' (purchases.products) ayarındaki ürünlerle eşleşmelidir; burada karşılığı olmayan bir ürün (ör. AI kredi paketi) hiç komisyon doğurmaz. Komisyon, satın alma mağaza tarafından onaylanıp kullanıcıya premium tanımlandıktan sonra salon sahibinin kazanç kaydına \'beklemede\' olarak eklenir; kullanıcıya ekstra ücret yansıtılmaz. Değer, salonlarla yapılan iş ortaklığının ticari/hukuki şartları netleşene kadar geçici konmuş bir rakamdır.', impact: 'Tutarı artırmak salon başına ödenen payı (ve şirket marjının düşmesini) büyütür; tutarı düşürmek veya bir ürün kimliğini yanlış yazmak salon ortağına hak ettiği komisyonun hiç ödenmemesine ve sözleşme anlaşmazlığına yol açabilir.', sensitive: true),
  ConfigField(key: 'economy.referral_commission_try', type: 'double', doc: ConfigDoc.server, group: 'economy', label: 'Referans komisyonu (₺, sabit)', description: 'Bir kişisel referans kodu kullanıldığında kodun sahibine yatırılacak sabit komisyon tutarını Türk Lirası cinsinden belirler (yüzde değil, sabit tutar). Kod kullanıldığı anda bu tutar sunucu tarafından kullanıcının komisyon kaydına \'ödenmeyi bekliyor\' durumunda yazılır; bu gerçek, ödenmesi gereken bir alacak doğurur. Salon atfetme komisyonu ayrı bir ayarla (economy.gym_commission_try) yönetilir, bu alanla karıştırılmamalıdır.', impact: 'Yükseltmek her başarılı kişisel referans için ödenmesi gereken gerçek para tutarını doğrudan artırır, düşürmek ise kullanıcıların referans programından kazandığı geliri azaltarak memnuniyetsizliğe yol açabilir.', sensitive: true, min: 0, max: 1000),
  ConfigField(key: 'economy.referral_max_uses', type: 'int', doc: ConfigDoc.server, group: 'economy', label: 'Referans kodu maksimum kullanım', description: 'Bir kişisel referans kodunun en fazla kaç farklı kişi tarafından kullanılabileceğinin varsayılan değeridir. Bugün bir kullanıcı kodunu ilk oluşturduğunda bu limit, uygulamanın sabit olarak belirlediği sayıyla (10) kodun kendi kaydına anında yazılır; buradaki ayar yalnızca bir kodun kayıtlı limiti olmadığı istisnai/bozuk durumlarda sunucu tarafında yedek olarak devreye girer. Yani bu alanı değiştirmek, zaten var olan referans kodlarının limitini değiştirmez.', impact: 'Bu değeri değiştirmek, kod oluşturma akışı bu ayarı okuyacak şekilde güncellenmeden önce mevcut kullanıcı davet kodları üzerinde neredeyse hiç gözlemlenebilir etki yaratmaz.', min: 1, max: 1000),
  ConfigField(key: 'economy.referral_reward_days', type: 'int', doc: ConfigDoc.server, group: 'economy', label: 'Referans ödülü (gün)', description: 'Bir kişisel referans (arkadaş davet) kodu kullanıldığında hem kodu kullanan hem de kodun sahibine kaç günlük ücretsiz premium deneme verileceğini belirler. Bu değer her kod kullanımında sunucu tarafından o anda geçerli ayardan okunur ve iki tarafa da aynı süre uygulanır. Salon (gym) davet kodları bu ödülü almaz; onlar ayrı bir atfetme/komisyon mekanizması kullanır.', impact: 'Yükseltmek her başarılı referans başına verilen ücretsiz premium süresini (dolayısıyla kaybedilen abonelik gelirini) doğrudan artırır, düşürmek ise referans programının cazibesini azaltır.', sensitive: true, min: 1, max: 90),
  ConfigField(key: 'economy.streak_freeze_grant_amount', type: 'int', doc: ConfigDoc.server, group: 'economy', label: 'Yeni kullanıcı streak dondurma hediyesi', description: 'Yeni kayıt olan bir kullanıcıya hesabı açılırken \'hoş geldin hediyesi\' olarak kaç adet streak (seri) dondurma hakkı tanınacağını ifade eder; bir dondurma hakkı, kullanıcı bir gün uygulamayı açmayı unuttuğunda gün serisinin sıfırlanmasını bir kerelik engeller. Bugün itibarıyla bu alan uygulama tarafından fiilen okunmuyor: hediye miktarı hâlâ istemci (mobil uygulama) kodunda sabit olarak 1 yazılıdır ve güvenlik kuralları yeni hesap oluşturulurken bu değeri 0-1 aralığına zaten sabitler. Bu nedenle panelden başka bir sayı girmek, sunucu tarafında bu alanı okuyan bir yazım yolu kurulana kadar gerçek davranışı değiştirmez.', impact: 'Bugün panelden değiştirmenin uygulamada hiçbir karşılığı yoktur; gerçek hediye miktarı, sunucu tarafı bu alanı okumaya başlayana kadar istemci kodundaki sabit değer olan 1\'de kalmaya devam eder.', min: 0, max: 5),
  ConfigField(key: 'endpoints.ai_proxy_url', type: 'string', doc: ConfigDoc.client, group: 'ai', label: 'AI proxy URL (override)', description: 'Uygulamanın AI isteklerini OpenRouter\'a doğrudan değil, API anahtarını cihazda hiç bulundurmayan bir sunucu (Cloud Function) proxy\'si üzerinden göndermesini sağlayan adrestir. Bu alan boş olduğu sürece uygulama hâlâ etkin olan eski Firebase Remote Config\'teki proxy adresini kullanmaya devam eder; burada dolu bir değer girildiğinde bu adres onun yerine kullanılır. Yayın (release) sürümünde her iki kaynak da boşsa uygulama AI isteğini reddeder, cihazdaki anahtarla asla doğrudan OpenRouter\'a düşmez.', impact: 'Hatalı/erişilemez bir adres yazmak AI özelliklerini üretimde kullanılamaz hale getirir; bu alanı boş bırakmak bugün Remote Config yedeği sayesinde güvenlidir ama o yedek ileride kaldırıldığında bu alanın canlıda dolu ve doğru olması zorunlu hale gelecektir.', sensitive: true),
  ConfigField(key: 'engagement.contrib_leaderboard_groups_per_run', type: 'int', doc: ConfigDoc.server, group: 'ops_caps', label: 'Canlı katkı panosu — çalıştırma başına grup sayısı', description: 'Canlı \'grup içinde bu hafta kim önde\' panosunu her 15 dakikada bir güncelleyen arka plan işinin, tek çalıştırmada işleyeceği maksimum grup sayısıdır. İşlem verimliliği/performans ayarıdır, kullanıcıya doğrudan görünmez; engagement.weekly_contrib_groups_per_run ile aynı mantığı taşır ama farklı (15 dakikalık, ödül değil görüntüleme amaçlı) işi besler. Grup sayısı bu sınırı aşarsa, sorgu bir sıralama kullanmadığından sınırın dışında kalan bazı grupların canlı panosu hiç güncellenmeyebilir.', impact: 'Çok yüksek bir değer her 15 dakikalık çalıştırmanın süresini ve maliyetini artırır; çok düşük bir değer, grup sayısı arttıkça bazı grupların canlı katkı panosunun güncellenmemesi riskini doğurur.', min: 10, max: 5000),
  ConfigField(key: 'engagement.contrib_leaderboard_top_n', type: 'int', doc: ConfigDoc.server, group: 'gamification_server', label: 'Canlı katkı panosu — gösterilen üye sayısı', description: 'Bir grubun \'şu an kim önde\' canlı katkı panosunda gösterilecek üye sayısıdır; kullanıcıların uygulamada gerçekten gördüğü bir liste uzunluğudur. Hafta henüz kapanmadan, o haftaki katkı puanlarına göre her 15 dakikada bir yeniden hesaplanır. Haftalık AI kredisi ödülü kazanan sayısını belirleyen engagement.weekly_top_n\'den bağımsızdır; bu değer yalnızca görüntülemeyi etkiler, dağıtılan ödülü değiştirmez.', impact: 'Değerin artırılması panoda daha fazla üyenin görünmesini sağlar, düşürülmesi listeyi kısaltır — her iki durumda da dağıtılan ödülü etkilemez.', min: 1, max: 50),
  ConfigField(key: 'engagement.credit_table', type: 'map<string,object>', doc: ConfigDoc.server, group: 'gamification_server', label: 'AI kredi kazanım tablosu', description: 'Kullanıcıların \'alınan etkileşim\' karşılığında ne kadar AI kredisi kazanacağını belirleyen tablo. Dört kaynak vardır: gönderi reaksiyonları, yorum beğenileri, paylaşılan bir plan şablonunun başka biri tarafından kabul edilmesi ve haftalık grup katkı sıralamasında ilk 3\'e girme. Her kaynak için kredi miktarı, günlük veya haftalık üst sınır ve (reaksiyon/beğenide) kaç farklı kişiden etkileşim gelmesi gerektiği ayrı ayrı tanımlıdır. Kazanılan kredi kullanıcının AI kredi bakiyesine eklenir ve günlük ücretsiz AI hakkı bittiğinde ekstra sorgu hakkı olarak harcanır; premium kullanıcılarda kredi ve tavan değerleri otomatik olarak 2 katına çıkar.', impact: 'Değerlerin yükseltilmesi kullanıcıların daha kolay ve daha fazla ücretsiz AI kredisi kazanmasını, dolayısıyla AI maliyetini artırır; düşürülmesi etkileşim ve katkı ödüllerini zayıflatarak kullanıcı motivasyonunu azaltır.', sensitive: true),
  ConfigField(key: 'engagement.weekly_candidate_buffer', type: 'int', doc: ConfigDoc.server, group: 'ops_caps', label: 'Haftalık aday tampon boyutu', description: 'Haftalık ödül hesabında her grup için puana göre en yüksek kaç adayın sorgudan çekileceğini belirleyen dahili bir teknik ayardır; kullanıcıya doğrudan görünmez. Bu aday havuzundan, yalnızca uygunluk şartlarını karşılayanlar arasından haftanın kazananları (weekly_top_n kadar) seçilir. Değer düşük tutulur ve havuzdaki adayların çoğu uygunluk şartını karşılamazsa, o hafta o grup için beklenenden az sayıda (hatta hiç) kazanan belirlenebilir.', impact: 'Değerin çok düşük olması bazı haftalarda beklenen sayıda kazanan bulunamamasına yol açabilir; gereğinden yüksek olması gereksiz sorgu/okuma maliyeti yaratır.', min: 1, max: 100),
  ConfigField(key: 'engagement.weekly_contrib_groups_per_run', type: 'int', doc: ConfigDoc.server, group: 'ops_caps', label: 'Haftalık katkı — çalıştırma başına grup sayısı', description: 'Haftalık grup katkı ödülünü hesaplayan ve her 24 saatte bir çalışan arka plan işinin, tek seferde tarayacağı maksimum grup sayısıdır. Kullanıcıya yönelik bir ayar değildir; işlem verimliliği/performans ayarıdır ve panelde doğrudan görünür bir etkisi yoktur. Sorgu belirli bir sıralama kullanmadığından, toplam grup sayısı bu sınırı aşarsa sınırın dışında kalan gruplar yalnızca o çalıştırmada değil, sürekli olarak atlanabilir.', impact: 'Çok yüksek bir değer çalıştırmanın süresini ve okuma maliyetini artırır; çok düşük bir değer, grup sayısı arttıkça bazı grupların haftalık ödül hesabına hiç girmemesi riskini doğurur.', min: 10, max: 5000),
  ConfigField(key: 'engagement.weekly_min_active_members', type: 'int', doc: ConfigDoc.server, group: 'gamification_server', label: 'Haftalık grup katkı — minimum aktif üye', description: 'Bir topluluk grubunda, haftalık katkı ödülünün (haftanın en aktif üyelerine AI kredisi verilmesi) o hafta için hesaplanabilmesi için gereken minimum katkı sağlamış üye sayısıdır. Bu sayının altında katkı sağlayan üyesi olan gruplar o hafta ödül sürecine hiç dahil edilmez, yani hiçbir kazanan belirlenmez. Canlı \'şu an kim önde\' panosunu etkilemez; sadece haftalık AI kredisi ödülünün verilip verilmeyeceğini belirler.', impact: 'Yüksek bir değer küçük veya yeni grupların haftalık ödül kazanmasını zorlaştırır; çok düşük bir değer neredeyse hiç aktif olmayan gruplara bile ödül dağıtılmasına yol açar.', sensitive: true, min: 2, max: 50),
  ConfigField(key: 'engagement.weekly_top_n', type: 'int', doc: ConfigDoc.server, group: 'gamification_server', label: 'Haftalık kazanan sayısı', description: 'Bir grupta haftalık katkı sıralamasına göre AI kredisi kazanacak, haftanın \'ilk N\'i\' sayılan üye sayısıdır. Hafta kapandıktan sonra çalışan ödül işi, en yüksek puanlı ve uygunluk şartlarını (hesap yaşı, e-posta doğrulama, kısıtlama durumu) karşılayan bu kadar üyeyi ödüllendirir. Uygun olmayan bir üye atlanır ve yerine sıradaki uygun üye bu sayıyı tamamlamak üzere seçilir.', impact: 'Değerin artırılması bir grupta haftalık ödül kazanan kullanıcı sayısını ve dağıtılan toplam AI kredisini artırır, düşürülmesi ödülü daha az kişiyle sınırlar.', min: 1, max: 20),
  ConfigField(key: 'features.chat', type: 'bool', doc: ConfigDoc.critical, group: 'features', label: 'Sohbet', description: 'Panelde \'Sohbet\' başlığıyla değiştirilebilir bir anahtar olarak durur, ancak şu anda hiçbir ekran bu bayrağı kontrol etmiyor. Sohbet ekranları bu değerden bağımsız olarak herkese açık şekilde çalışmaya devam eder.', impact: 'Bu alanın şu anda hiçbir etkisi yok; değiştirmek güvenlidir ama hiçbir şeyi değiştirmez.'),
  ConfigField(key: 'features.coach', type: 'bool', doc: ConfigDoc.critical, group: 'features', label: 'Koç ekosistemi', description: 'Koç ekosisteminin uygulama içindeki giriş noktalarını (yan menü, hızlı işlemler, keşfet sekmesi, rol kartı) topluca açıp kapatan ana anahtardır. Kapatıldığında koçlukla ilgili tüm giriş noktaları gizlenir ve koç ekranlarına ulaşılamaz; veriler silinmez, yalnızca erişim gizlenir. Ayrı bir kademeli açılım yüzdesi (rollout.coach) ile birlikte çalışır.', impact: 'Kapatmak, koç ekosisteminin tüm giriş noktalarını tüm kullanıcılar için anında gizler; hassas alan olarak işaretlidir ve kaydetmek için onay ile gerekçe gerekir.', sensitive: true),
  ConfigField(key: 'features.community', type: 'bool', doc: ConfigDoc.critical, group: 'features', label: 'Topluluk', description: 'Panelde \'Topluluk\' başlığıyla değiştirilebilir bir anahtar olarak durur, ancak şu anda hiçbir ekran bu bayrağı kontrol etmiyor — ne açık ne de kapalı değeri herhangi bir ekranı gösterip gizliyor. İleride topluluk özelliğine bir açma/kapama anahtarı eklenmek istendiğinde kullanılması planlanan, bugün itibarıyla işlevsiz bir alandır.', impact: 'Bu alanın şu anda hiçbir etkisi yok; değiştirmek güvenlidir ama hiçbir şeyi değiştirmez.'),
  ConfigField(key: 'features.fitness_twin', type: 'bool', doc: ConfigDoc.critical, group: 'features', label: 'Fitness ikizi (AI)', description: 'Yapay zekâ destekli \'fitness ikizi\' ekranının bir açma/kapama anahtarı olması amaçlanmıştır ve daha önce hiçbir yerde okunmayan eski bir ayarın yerine geçmek üzere eklenmiştir. Ancak bugün itibarıyla da bu bayrağı kontrol eden herhangi bir ekran yok — fitness ikizi ekranı bu değerden bağımsız olarak herkese görünür durumdadır.', impact: 'Bu alanın şu anda hiçbir etkisi yok; değiştirmek güvenlidir ama fitness ikizi özelliğini açıp kapatmaz.'),
  ConfigField(key: 'features.food_scan', type: 'bool', doc: ConfigDoc.critical, group: 'features', label: 'Yemek fotoğrafı tarama', description: 'Panelde \'Yemek fotoğrafı tarama\' başlığıyla değiştirilebilir bir anahtar olarak durur, ancak şu anda hiçbir ekran bu bayrağı kontrol etmiyor. Fotoğrafla yemek tanıma akışı bu değerden bağımsız olarak çalışmaya devam eder.', impact: 'Bu alanın şu anda hiçbir etkisi yok; değiştirmek güvenlidir ama hiçbir şeyi değiştirmez.'),
  ConfigField(key: 'features.gym', type: 'bool', doc: ConfigDoc.critical, group: 'features', label: 'Spor salonu ekosistemi', description: 'Spor salonu ekosisteminin uygulama içindeki giriş noktalarını (yan menü, hızlı işlemler, keşfet sekmesi ve rol kartındaki \'Spor Salonu\' bağlantıları) topluca açıp kapatan ana anahtardır. Kapatıldığında bu giriş noktaları kullanıcılara gösterilmez ve salon ekranlarına ulaşılamaz; mevcut salon verileri silinmez, yalnızca erişim gizlenir. Bu anahtar ayrıca ayrı bir kademeli açılım yüzdesiyle (rollout.gym) birlikte çalışır — anahtar açık görünse bile, kademeli açılımın dışında kalan kullanıcılar özelliği yine göremez.', impact: 'Kapatmak, spor salonu ekosisteminin tüm giriş noktalarını tüm kullanıcılar için anında gizler; hassas alan olarak işaretlidir ve kaydetmek için onay ile gerekçe gerekir.', sensitive: true),
  ConfigField(key: 'features.gym_attribution', type: 'bool', doc: ConfigDoc.critical, group: 'features', label: 'Salon atfetme/komisyon UI', description: 'Salon panelindeki atfetme (hangi üyenin hangi salondan geldiği) ve komisyon/kazanç istatistikleri bölümünü açıp kapatan anahtardır. Davet kodu özelliğinden bağımsızdır; bu istatistik bölümünde bir sorun çıkarsa, zaten çalışan davet kodu özelliğini kapatmaya gerek kalmadan yalnızca bu bölüm kapatılabilir.', impact: 'Kapatmak yalnızca atfetme/kazanç istatistikleri bölümünü gizler; davet kodu özelliğini veya panelin geri kalanını etkilemez.'),
  ConfigField(key: 'features.gym_invite_codes', type: 'bool', doc: ConfigDoc.critical, group: 'features', label: 'Salon davet kodları', description: 'Salon panelindeki davet kodu üretimi, QR kod ve afiş (poster) dışa aktarma bölümünü açıp kapatan anahtardır. Kapatıldığında yalnızca bu bölüm salon panelinden gizlenir; panelin diğer bölümleri etkilenmez.', impact: 'Kapatmak yalnızca davet kodu/QR/afiş bölümünü gizler; salon panelinin geri kalanını etkilemez.'),
  ConfigField(key: 'features.marketplace', type: 'bool', doc: ConfigDoc.critical, group: 'features', label: 'Pazar yeri (genel)', description: 'Panelde \'Pazar yeri (genel)\' başlığıyla değiştirilebilir bir anahtar olarak durur, ancak şu anda hiçbir ekran bu bayrağı kontrol etmiyor — features.programs\'tan farklı olarak bu alanın bugün hiçbir görünür karşılığı yoktur. Salon/koç ekosistemiyle kavramsal olarak örtüştüğü için ileriye dönük bir tedbir olarak hassas işaretlenmiştir.', impact: 'Bu alanın şu anda hiçbir etkisi yok; yine de ileride hızla devreye alınabileceği için hassas alan olarak işaretlidir ve kaydetmek için onay ile gerekçe gerekir.', sensitive: true),
  ConfigField(key: 'features.meal_plan_templates', type: 'bool', doc: ConfigDoc.critical, group: 'features', label: 'Plan şablonları', description: 'Koç ve salon panellerindeki plan şablonu oluşturma/kütüphane bölümünü, koç/salon anahtarlarından bağımsız olarak açıp kapatan anahtardır. Kapatıldığında hem koç hem de salon panelinde yalnızca şablonlarla ilgili bölüm gizlenir; panelin geri kalanı normal çalışmaya devam eder. Böylece şablon üretiminde bir sorun çıktığında koç veya salon panelinin tamamını kapatmaya gerek kalmaz.', impact: 'Kapatmak yalnızca plan şablonu bölümünü gizler, koç/salon panellerinin geri kalanını etkilemez — dar kapsamlı, düşük risklidir.'),
  ConfigField(key: 'features.nutrition_analytics', type: 'bool', doc: ConfigDoc.critical, group: 'features', label: 'Beslenme analitiği', description: 'Adından ana sayfadaki beslenme analitiği simgesinin erişilebilirliğini kontrol ettiği düşünülebilir, ancak bunu gerçekte belirleyen yer, bu panelden ayrı bir sistem olan Firebase Remote Config\'teki kendi \'feature_nutrition_analytics\' değeridir. Bu alanı burada değiştirmek bugün itibarıyla o simgenin görünürlüğünü etkilemez.', impact: 'Bu alanı burada değiştirmenin şu anda gözle görülür bir etkisi yoktur — gerçek anahtar Firebase Remote Config tarafında ayrıca yönetilmektedir.'),
  ConfigField(key: 'features.photo_analysis', type: 'bool', doc: ConfigDoc.critical, group: 'features', label: 'Fotoğraf analizi (AI)', description: 'Yapay zekâ ile fotoğraftan yemek/besin analizi özelliğinin bir açma/kapama anahtarı olması amaçlanmıştır ve daha önce hiçbir ekran tarafından okunmayan eski bir ayarın yerine geçmek üzere eklenmiştir. Ancak bugün itibarıyla da bu bayrağı kontrol eden herhangi bir ekran yok — fotoğraf analizi akışı bu değerden bağımsız olarak çalışmaya devam ediyor.', impact: 'Bu alanın şu anda hiçbir etkisi yok; değiştirmek güvenlidir ama fotoğraf analizi özelliğini açıp kapatmaz.'),
  ConfigField(key: 'features.programs', type: 'bool', doc: ConfigDoc.critical, group: 'features', label: 'Programlar (pazar yeri)', description: 'Program pazarı (\'Programlar\') özelliğinin keşfet sekmesi ve yan menüdeki giriş noktalarını açıp kapatan anahtardır. Kapatıldığında kullanıcılar programlar bölümüne bu giriş noktalarından ulaşamaz. Ayrı bir kademeli açılım yüzdesi (rollout.programs) ile birlikte çalışır — anahtar açık olsa da kademeli açılımın dışındaki kullanıcılar özelliği göremeyebilir.', impact: 'Kapatmak, programlar bölümünün giriş noktalarını tüm kullanıcılar için anında gizler; hassas alan olarak işaretlidir ve kaydetmek için onay ile gerekçe gerekir.', sensitive: true),
  ConfigField(key: 'features.referral', type: 'bool', doc: ConfigDoc.critical, group: 'features', label: 'Referans sistemi', description: 'Panelde \'Referans sistemi\' başlığıyla değiştirilebilir bir anahtar olarak durur, ancak şu anda hiçbir ekran bu bayrağı kontrol etmiyor. Referans kodu oluşturma/kullanma akışı bu değerden bağımsız olarak çalışmaya devam eder.', impact: 'Bu alanın şu anda hiçbir etkisi yok; değiştirmek güvenlidir ama hiçbir şeyi değiştirmez.'),
  ConfigField(key: 'features.squad', type: 'bool', doc: ConfigDoc.critical, group: 'features', label: 'Squad', description: 'Yan menüdeki \'Squad\' giriş noktasını açıp kapatan anahtardır. Kapatıldığında Squad bağlantısı yan menüden kaybolur. Gym/Koç/Programlar anahtarlarının aksine hassas olarak işaretli değildir ve ayrı bir kademeli açılım yüzdesiyle (rollout.squad) birlikte çalışır.', impact: 'Kapatmak yalnızca yan menüdeki Squad girişini gizler; diğer ekosistem anahtarlarına göre daha dar kapsamlı ve düşük risklidir.'),
  ConfigField(key: 'features.voice_assistant', type: 'bool', doc: ConfigDoc.critical, group: 'features', label: 'Sesli asistan', description: 'Adından sesli asistan özelliğini açıp kapattığı düşünülebilir, ancak sesli asistan katmanının gösterilip gösterilmeyeceğine gerçekte karar veren yer, bu panelden tamamen ayrı bir sistem olan Firebase Remote Config\'teki kendi \'feature_voice_assistant\' değeridir. Bu yüzden bu alanı burada değiştirmek, sesli asistanın kullanıcılara görünüp görünmeyeceğini bugün itibarıyla etkilemez; gerçek anahtar Firebase Remote Config tarafında ayrıca yönetilmektedir.', impact: 'Bu alanı burada değiştirmenin şu anda gözle görülür bir etkisi yoktur — sesli asistanı gerçekten açıp kapatmak için Firebase Remote Config tarafındaki ayrı anahtarın değiştirilmesi gerekir.'),
  ConfigField(key: 'features.weekly_recap', type: 'bool', doc: ConfigDoc.critical, group: 'features', label: 'Haftalık özet', description: 'Haftalık özet ekranının bir açma/kapama anahtarı olması amaçlanmıştır ve daha önce hiçbir ekran tarafından okunmayan eski bir ayarın yerine geçmek üzere eklenmiştir. Ancak bugün itibarıyla da bu bayrağı kontrol eden herhangi bir ekran yok — haftalık özet kartı ve ekranı bu değerden bağımsız olarak herkese görünür durumdadır.', impact: 'Bu alanın şu anda hiçbir etkisi yok; değiştirmek güvenlidir ama haftalık özet özelliğini açıp kapatmaz.'),
  ConfigField(key: 'gamification.achievement_points', type: 'map<string,int>', doc: ConfigDoc.server, group: 'gamification_server', label: 'Başarım puanları', description: 'Her başarım rozetinin (ör. ilk yemek kaydı, 7/30/100 günlük seri, itibar kademeleri, seviye 50, salon düzenlisi) kazanıldığı anda kullanıcıya kaç XP puanı ekleyeceğini belirler; rozetin ne zaman/nasıl kazanılacağını değil, sadece kazanıldığında verilecek XP karşılığını belirler. Bu liste, uygulamanın rozet/başarım ekranında kullanıcıya gösterilen puanlarla ayrı, elle senkronize tutulan bir kopyadır. Bu alan bugün sunucu tarafında canlı olarak okunmuyor — sunucu kendi sabit tablosunu kullanmaya devam ediyor — bu yüzden panelden yapılan bir değişiklik ne gerçek ödülü ne de ekranda gösterilen puanı değiştirir.', impact: 'Bugün panelden değiştirmenin pratik bir etkisi yoktur; ileride canlı hale getirildiğinde puanları yükseltmek XP ekonomisini şişirir, düşürmek kullanıcıların beklediği ödülü azaltır ve ekrandaki gösterim ayrıca güncellenmezse kullanıcıya gösterilen puanla gerçekte verilen puan birbirini tutmaz hale gelir.', sensitive: true),
  ConfigField(key: 'gamification.group_streak_achievement_threshold', type: 'int', doc: ConfigDoc.server, group: 'gamification_server', label: 'Grup streak başarım eşiği (hafta)', description: 'Bir kullanıcının art arda kaç hafta boyunca grubunun haftalık katkı sıralamasında ilk 3\'e girmesi durumunda \'grup streak\' rozetini kazanacağını belirler (varsayılan 4 hafta); art arda kaçırılan bir hafta bu sayacı sıfırlar. Bu alan bugün sunucu tarafında canlı olarak okunmuyor; sunucu kodu hâlâ sabit değeri (4) kullanıyor, yani panelden değiştirmenin şu an için gerçek bir etkisi yoktur.', impact: 'Bugün panelden değiştirmenin uygulamada bir karşılığı yoktur; ileride canlı hale getirildiğinde eşiği yükseltmek rozeti neredeyse ulaşılamaz hale getirebilir, düşürmek ise anlamsızlaşacak kadar kolaylaştırabilir.', min: 1, max: 52),
  ConfigField(key: 'gamification.gym_regular_checkin_threshold', type: 'int', doc: ConfigDoc.server, group: 'gamification_server', label: '\'Düzenli salon üyesi\' check-in eşiği', description: '\'Düzenli salon üyesi\' rozetinin kazanılması için gereken, sunucu tarafından doğrulanmış toplam salon check-in sayısını belirler (varsayılan 15); sayaç kullanıcının beyanına değil, sunucunun kendi tuttuğu gerçek check-in geçmişine dayanır. Bu alan bugün sunucu tarafında canlı olarak okunmuyor; sunucu kodu hâlâ sabit değeri (15) kullanıyor, yani panelden değiştirmenin şu an için gerçek bir etkisi yoktur.', impact: 'Bugün panelden değiştirmenin uygulamada bir karşılığı yoktur; ileride canlı hale getirildiğinde eşiği yükseltmek rozetin kazanılmasını zorlaştırır, düşürmek ise rozeti daha az düzenli kullanıcılara da erken vererek anlamını sulandırır.', min: 1, max: 100),
  ConfigField(key: 'gamification.level_curve_coefficient', type: 'int', doc: ConfigDoc.client, group: 'gamification', label: 'Seviye eğrisi katsayısı', description: 'Kullanıcıların toplam XP\'sinin (deneyim puanının) hangi seviyeye karşılık geldiğini belirleyen formüldeki katsayıdır (bir seviyeye ulaşmak için gereken toplam XP = katsayı × seviye × (seviye−1)). Katsayı yükseldikçe aynı XP ile ulaşılan seviye düşer (seviye atlamak zorlaşır), düşürüldükçe aynı XP ile ulaşılan seviye yükselir (seviye atlamak kolaylaşır). Seviye; profil ekranında, ilerleme çubuklarında ve itibar kademesi (newcomer/active/contributor/expert/legend) eşiklerinin temelinde kullanılır.', impact: 'Bu katsayıyı değiştirmek yeni kazanılacak XP\'yi değil, MEVCUT kullanıcıların toplam XP\'sinin karşılık geldiği seviyeyi geriye dönük olarak değiştirir — herkesi aynı anda yükseltir veya düşürür, bu yüzden dar bir aralıkla sınırlanmıştır ve onay + gerekçe zorunludur.', sensitive: true, min: 10, max: 200),
  ConfigField(key: 'gamification.local_utc_offset_hours', type: 'int', doc: ConfigDoc.server, group: 'gamification_server', label: 'Yerel saat dilimi ofseti (UTC+)', description: 'Uygulamanın \'yerel gün/hafta\' hesaplarında kullandığı UTC ofsetini belirler (Türkiye için sabit +3, 2016\'dan beri yaz saati uygulaması olmadığından değişmiyor); sessiz saat bildirim penceresi ile haftalık/günlük AI kredisi limitlerinin ve hafta anahtarının hangi yerel saatte sıfırlanacağını etkiler. Ancak bu alan kısmen canlıdır: günlük XP limitlerinin ve günlük seri (streak) ödülünün sıfırlanma anı bu ayarı değil, sunucudaki ayrı bir sabit +3 değerini kullanmaya devam eder. Bu yüzden alanı değiştirmek sistemler arasında gün sınırı tutarsızlığı yaratabilir.', impact: 'Türkiye dışına açılma gibi istisnai bir durum dışında değiştirmek sessiz saatlerin ve haftalık/günlük kredi sıfırlamasının yanlış yerel saatte tetiklenmesine yol açar; alan yalnızca kısmen canlı okunduğundan günlük XP/seri sıfırlaması diğer sistemlerle saat bakımından uyumsuz kalmaya devam eder.', min: -12, max: 14),
  ConfigField(key: 'gamification.max_level', type: 'int', doc: ConfigDoc.client, group: 'gamification', label: 'Maksimum seviye', description: 'Seviye hesaplamasının arayabileceği en yüksek değerdir — gerçek bir oyun içi seviye tavanı değil, sonsuz döngüyü önleyen teknik bir güvenlik sınırıdır. Varsayılan 999 seviyesine ulaşmak ~49 milyon XP gerektirir ve normal kullanımda pratikte erişilemez. gamification.level_curve_coefficient ile birlikte kullanıcı seviyesinin nasıl hesaplandığını belirler.', impact: 'Bu değeri gereğinden çok düşürmek, gerçekten çok yüksek XP biriktirmiş uç durumdaki bir kullanıcının seviyesini olduğundan düşük göstermesine/sabitlemesine yol açabilir; normal aralıkta değiştirmenin pratikte gözlenebilir bir etkisi yoktur.', min: 50, max: 9999),
  ConfigField(key: 'gamification.max_xp_events_per_call', type: 'int', doc: ConfigDoc.server, group: 'gamification_server', label: 'syncProgress çağrısı başına maksimum XP olayı', description: 'Kullanıcının anlık ilerleme senkronizasyonu sırasında tek seferde bildirebileceği XP olayı (yemek kaydı, tarif pişirme, gönderi, yorum, tepki gibi) sayısının üst sınırını belirler; bu sınırın üzerindeki olaylar hataya yol açmadan sessizce yok sayılır. Bu, tek bir isteğin işleyeceği yükü sınırlayan bir güvenlik/performans tavanıdır — kullanıcının günde kazanabileceği toplam XP\'yi belirlemez, o zaten her olay türünün kendi günlük üst sınırıyla (XP tablosundaki dailyCap) sınırlıdır. Bu alan bugün sunucu tarafında canlı olarak okunmuyor; kod hâlâ sabit değeri (10) kullanıyor, yani panelden değiştirmenin şu an için gerçek bir etkisi yoktur.', impact: 'Bugün panelden değiştirmenin uygulamada bir karşılığı yoktur; ileride canlı hale getirildiğinde değeri çok yükseltmek tek istekte aşırı işlem yüküne, çok düşürmek ise bir defada gönderilen bazı olayların sessizce atlanmasına yol açar.', min: 1, max: 100),
  ConfigField(key: 'gamification.tier_level_floor', type: 'map<string,int>', doc: ConfigDoc.server, group: 'gamification_server', label: 'İtibar kademesi seviye eşikleri', description: 'Kullanıcı seviyesine göre hangi itibar kademesine (yeni üye/aktif/katkı sağlayan/uzman/efsane) yerleştirileceğini belirleyen seviye eşikleridir; bu kademe profilde rozet/etiket olarak görünür ve ilgili kademe başarımlarını tetikler. Değerler yeni-üyeden efsaneye doğru kesinlikle artan sırada olmalıdır; panel bunu kaydederken zaten zorunlu tutar. Bu alan bugün sunucu tarafında canlı olarak okunmuyor; sunucu kodu hâlâ sabit eşikleri (1/5/10/20/35) kullanıyor, yani panelden değiştirmenin şu an için gerçek bir etkisi yoktur.', impact: 'Bugün panelden değiştirmenin uygulamada bir karşılığı yoktur; ileride canlı hale getirildiğinde artmayan/bozuk bir sıralama kademe hesaplamasını sessizce bozar, eşikleri aşırı değiştirmek ise kademelerin ve onlara bağlı rozetlerin anlamını zedeler.', sensitive: true),
  ConfigField(key: 'gamification.xp_table', type: 'map<string,object>', doc: ConfigDoc.server, group: 'gamification_server', label: 'XP tablosu', description: 'Her XP olayı türü için (yemek kaydı, günlük seri, salon check-in, gönderi, yorum, tepki, tarif pişirme, plan teklifi kabulü) kaç puan verileceğini ve günlük üst sınırı (dailyCap) belirler; kullanıcı profilindeki seviye ve XP ilerleme çubuğu doğrudan bu puanların toplamından hesaplanır. Bu tablo yalnızca genel XP akışında değil, salon check-in\'ini işleyen akışlarda ve plan teklifi kabulünü işleyen akışta (sırasıyla presence.js, gym.js ve templates.js dosyaları) da aynı ortak fonksiyon üzerinden anlık okunur; yani buradaki bir değişiklik ayrı bir kod değişikliği gerekmeden yaklaşık bir dakika içinde (önbellek süresi) dört akışın tamamına birden yansır. \'dailyCap\' değeri boş (null) bırakılan satırlar (ör. template_accepted) günlük sınırsızdır; bir satırı silmek veya bozuk bırakmak o eylem türü için puan verilmesini durdurabilir.', impact: 'Puanları veya günlük limitleri yükseltmek XP ekonomisini şişirip seviye/rozet ilerlemesini hızlandırır; düşürmek ise beklenen ödülü aniden keser ve tablo dört farklı akışı aynı anda etkilediğinden herhangi bir değişiklik tüm oyunlaştırma dengesini bir kerede değiştirir.', sensitive: true),
  ConfigField(key: 'groups.activity_comments_scan_limit', type: 'int', doc: ConfigDoc.server, group: 'ops_caps', label: 'Aktivite skoru — yorum tarama limiti', description: 'Aktivite skoru hesaplanırken, gruba göre değil tüm sistem genelinde tek bir sorguda en fazla kaç yorumun taranacağını belirleyen dahili bir tarama sınırıdır. İşlem verimliliği/performans ayarıdır, kullanıcıya doğrudan görünmez; bu sınır o çalıştırmadaki tüm gruplar arasında paylaşılır.', impact: 'Çok yüksek bir değer her çalıştırmanın okuma maliyetini artırır; çok düşük bir değer, yorum hacminin yüksek olduğu dönemlerde bazı grupların aktivite skoruna yorumların eksik yansımasına yol açabilir.', min: 10, max: 5000),
  ConfigField(key: 'groups.activity_groups_per_run', type: 'int', doc: ConfigDoc.server, group: 'ops_caps', label: 'Aktivite skoru — çalıştırma başına grup sayısı', description: 'Grup aktivite skorunu her 15 dakikada bir yeniden hesaplayan arka plan işinin, tek çalıştırmada işleyeceği maksimum (herkese açık) grup sayısıdır. İşlem verimliliği/performans ayarıdır, kullanıcıya doğrudan görünmez. Sorgu bir sıralama kullanmadığından, herkese açık grup sayısı bu sınırı aşarsa sınırın dışında kalan bazı gruplar hiç skorlanmayabilir ve dolayısıyla \'en aktif gruplar\' listesinde hiç görünmeyebilir.', impact: 'Çok yüksek bir değer her 15 dakikalık çalıştırmanın süresini ve maliyetini artırır; çok düşük bir değer, herkese açık grup sayısı arttıkça bazı grupların hiç skorlanmaması riskini doğurur.', min: 10, max: 5000),
  ConfigField(key: 'groups.activity_half_life_hours', type: 'double', doc: ConfigDoc.server, group: 'ops_caps', label: 'Aktivite skoru yarı ömrü (saat)', description: 'Aktivite skorunda her bir olayın (mesaj, gönderi, yorum, yeni üye) yaşlandıkça ağırlığının ne hızla azalacağını belirleyen yarı ömür değeridir (saat) — örneğin varsayılan 6 saatte bir olayın skora katkısı yarıya iner. \'En aktif gruplar\' sıralamasının anlık patlamaları mı yoksa gün boyu süren istikrarlı aktifliği mi daha çok ödüllendirdiğini belirleyen gerçek bir algoritma parametresidir.', impact: 'Küçük bir değer sıralamayı çok yeni olaylara aşırı duyarlı ve dalgalı hale getirir; büyük bir değer sıralamanın daha yavaş değişmesini sağlar ama ani hareketliliği daha az öne çıkarır.', min: 1, max: 168),
  ConfigField(key: 'groups.activity_signal_limit', type: 'int', doc: ConfigDoc.server, group: 'ops_caps', label: 'Aktivite skoru — sinyal başına tarama limiti', description: 'Aktivite skoru hesaplanırken bir grubun mesaj, gönderi veya yeni üye sinyallerinin her biri için tek seferde en fazla kaç kaydın taranacağını belirleyen dahili bir tarama sınırıdır. İşlem verimliliği/performans ayarıdır, kullanıcıya doğrudan görünmez; günümüzde hiçbir grubun bu sınıra gerçekçi biçimde ulaşması beklenmez.', impact: 'Çok yüksek bir değer her çalıştırmanın okuma maliyetini artırır; çok düşük bir değer, olağanüstü yoğun bir grubun aktivite skorunun eksik hesaplanmasına yol açabilir.', min: 10, max: 5000),
  ConfigField(key: 'groups.activity_window_hours', type: 'int', doc: ConfigDoc.server, group: 'ops_caps', label: 'Aktivite skoru penceresi (saat)', description: 'Bir topluluk grubunun \'aktivite skorunun\' hesaplanmasında geriye dönük kaç saatlik mesaj, gönderi, yorum ve yeni üye verisinin dikkate alınacağını belirler. Bu skor, keşfet ekranındaki \'en aktif gruplar\' bölümünün sıralamasını belirleyen, kullanıcının doğrudan gördüğü bir sıralama algoritmasının parametresidir. Skor her 15 dakikada bir yeniden hesaplanır.', impact: 'Pencereyi kısaltmak sıralamayı yalnızca çok yakın zamandaki ani hareketliliğe duyarlı hale getirir, uzatmak ise daha eski etkileşimlerin de skora katkı vermesini sağlayarak sıralamanın daha yavaş değişmesine yol açar.', min: 1, max: 168),
  ConfigField(key: 'maintenance.enabled', type: 'bool', doc: ConfigDoc.critical, group: 'maintenance', label: 'Bakım modu', description: 'Uygulama genelinde tam ekran bakım duvarını açar veya kapatır. Açık olduğunda, oturum açmış veya açmamış fark etmeksizin tüm kullanıcılar (sürüm kontrolünden bile önce) doğrudan bakım ekranına yönlendirilir ve uygulamanın geri kalanına erişemez. Bu alan anlık izlenen bir belgede tutulduğundan, değişiklik uygulama yeniden başlatılmadan açık oturumlara da hemen yansır. Bir cihaz bakımın açık olduğunu bir kez gördüyse, bağlantısı kesilse bile siz kapatana kadar bakım ekranını göstermeye devam edebilir.', impact: 'Açmak tüm kullanıcıları anında ve istisnasız uygulama dışına atar; bu yüzden hassas alan olarak işaretlenmiştir ve kaydetmek için onay ile bir gerekçe metni gerekir.', sensitive: true),
  ConfigField(key: 'maintenance.message', type: 'map<string,string>', doc: ConfigDoc.critical, group: 'maintenance', label: 'Bakım mesajı (en/tr)', description: 'Bakım ekranında kullanıcıya gösterilen İngilizce/Türkçe mesaj metnidir. Cihazın dil ayarına göre uygun dildeki metin gösterilir; ilgili dil için metin boş bırakılırsa, uygulamanın kendi yerleşik varsayılan bakım mesajı gösterilir. Bu alan bakımın açık olup olmadığını etkilemez, yalnızca açıkken gösterilen açıklamayı belirler.', impact: 'Düşük risk — yalnızca bakım ekranındaki yazı değişir, bakımın kullanıcıları engelleyip engellememesini etkilemez.'),
  ConfigField(key: 'media.vision_daily_cap', type: 'int', doc: ConfigDoc.server, group: 'ai_server', label: 'Günlük Vision taraması limiti', description: 'Yüklenen görsellerin (gönderi fotoğrafları, profil fotoğrafları, salon görselleri) uygunsuz içerik (yetişkin/şiddet içerikli) olup olmadığını kontrol eden Cloud Vision taramasının günde en fazla kaç kez çalıştırılabileceğini belirleyen sabit bir maliyet tavanıdır. Bu sınıra ulaşıldığında, o gün için yeni yüklenen görseller taranmadan (silinme riski oluşmadan) doğrudan yayında kalır. Yaklaşık 1000 tarama, günlük olarak kabaca 1,5 ABD doları civarında bir maliyete denk gelir.', impact: 'Değerin yükseltilmesi daha fazla görselin güvenlik açısından taranmasını sağlar ama azami günlük Vision harcamasını doğrudan artırır; düşürülmesi maliyeti azaltır ama sınıra ulaşıldıktan sonra yüklenen görsellerin denetimsiz kalma riskini artırır.', sensitive: true, min: 10, max: 100000),
  ConfigField(key: 'moderation.action_rate_limit', type: 'object', doc: ConfigDoc.server, group: 'moderation', label: 'Moderasyon aksiyonu hız sınırı', description: 'Bir grup moderatörünün/sahibinin 10 dakika içinde en fazla kaç moderasyon işlemi (üye atma, yasaklama, susturma, susturma ya da yasağı kaldırma) yapabileceğini belirler; varsayılan ayar 10 dakikada 15 işlemdir ve aşıldığında 15 dakika boyunca yeni moderasyon işlemi yapılamaz. Amaç, gerçek bir moderatörün bir \'baskın\'ı tek seferde temizleyebilmesine izin verirken, ele geçirilmiş bir sahip/admin hesabının grubu toplu şekilde boşaltmasının etkisini sınırlamaktır.', impact: 'Gevşetmek ele geçirilmiş bir moderatör hesabının çok daha fazla üyeyi kitlesel olarak atıp yasaklayabilmesine izin verir; sıkılaştırmak gerçek bir moderatörün büyük bir baskını tek seferde temizleyememesine yol açar.', sensitive: true),
  ConfigField(key: 'moderation.appeal_rate_limit', type: 'object', doc: ConfigDoc.server, group: 'moderation', label: 'İtiraz gönderme hız sınırı', description: 'Bir kullanıcının 1 saat içinde en fazla kaç moderasyon itirazı gönderebileceğini belirler; varsayılan ayar 1 saatte 5 itirazdır ve aşıldığında kullanıcı 1 saat boyunca yeni itiraz gönderemez. Her moderasyon işlemine zaten yalnızca bir itiraz açılabildiğinden, bu sınır tek bir işleme değil, kısa sürede birçok farklı işleme art arda itiraz açılmasına karşı çalışır.', impact: 'Gevşetmek itiraz mekanizmasının spam amaçlı doldurulup gerçek itirazların moderatörler tarafından görülmesini zorlaştırmasına yol açar; sıkılaştırmak birden fazla haklı itirazı olan bir kullanıcının bunları kısa sürede gönderememesine neden olur.', sensitive: true),
  ConfigField(key: 'moderation.auto_restrict_flag_threshold', type: 'int', doc: ConfigDoc.server, group: 'moderation', label: 'Otomatik kısıtlama bayrak eşiği', description: 'Bir hesabın kendi davranışı yüzünden (kopya içerik paylaşma, karşılıklılık/yoğunlaşma şüphesi gibi) art arda kaç kez \'şüpheli\' işaretlendiğinde otomatik olarak gölge kısıtlamaya alınıp bundan sonra hiçbir etkileşimden kredi kazanamaz hale getirileceğini belirler. Kısıtlama kullanıcıya açıkça bildirilmez (\'gölge\' kısıtlama) ama itiraz yoluyla kaldırılabilir; alt sınırın 1 olması, 0 girilirse bu korumanın tamamen devre dışı kalacağı içindir.', impact: 'Eşiği düşürmek gerçek kullanıcıların birkaç yanlış-pozitif tespitle bile kredi kazanma hakkını tamamen kaybetmesine yol açar; yükseltmek kötü niyetli hesapların çok daha uzun süre kredi kazanmaya devam etmesine izin verir.', sensitive: true, min: 1, max: 50),
  ConfigField(key: 'moderation.checkin_rate_limit', type: 'object', doc: ConfigDoc.server, group: 'moderation', label: 'Check-in hız sınırı', description: 'Bir kullanıcının 1 saat içinde en fazla kaç salon check-in\'i yapabileceğini belirler; varsayılan ayar 1 saatte 6\'dır ve hem QR kod okutarak hem GPS/konumla yapılan check-in\'ler tek bir ortak bütçeyi paylaşır, yani iki yöntem birlikte kullanılarak sınır aşılamaz. Aşıldığında kullanıcı 1 saat boyunca yeni check-in yapamaz; gerçek bir salon ziyareti günde bir-iki kez olduğundan (ör. antrenman + ders), varsayılan zaten geniş bir paydır.', impact: 'Gevşetmek sahte check-in\'lerle salon liderlik tablosunun ve check-in XP\'sinin otomatik olarak şişirilmesine izin verir; sıkılaştırmak aynı saatte birden fazla gerçek check-in yapan bir kullanıcıyı engelleyebilir.', sensitive: true),
  ConfigField(key: 'moderation.comment_min_text_length', type: 'int', doc: ConfigDoc.server, group: 'moderation', label: 'Yorum minimum metin uzunluğu', description: 'Bir yorumun, aldığı beğeniler karşılığında yazarına bonus AI kredisi kazandırabilmesi için gereken minimum metin uzunluğunu belirler; yorum paylaşımını engellemez, sadece kredi kazanma uygunluğunu etkiler. Gönderilerdeki görsel istisnasının aksine yorumlar her zaman metin uzunluğuna göre değerlendirilir.', impact: 'Düşürmek kısa/anlamsız yorumların da kredi kazanmasına yol açar; yükseltmek samimi ama kısa yorum yazan kullanıcıların krediden mahrum kalmasına neden olur.', min: 0, max: 500),
  ConfigField(key: 'moderation.comment_rate_limit', type: 'object', doc: ConfigDoc.server, group: 'moderation', label: 'Yorum oluşturma hız sınırı', description: 'Bir kullanıcının 10 dakika içinde en fazla kaç yorum yazabileceğini belirler; varsayılan ayar 10 dakikada 30 yorumdur (yorumlaşma doğası gereği daha sık gerçekleştiğinden gönderi sınırından yüksek tutulmuştur) ve aşıldığında 15 dakika boyunca yorum yazılamaz. Genel akış ve salon sayfalarındaki yorumlar tek bir ortak bütçeyi paylaşır.', impact: 'Gevşetmek yorum bölümlerinin spam/flood ile doldurulmasına izin verir; sıkılaştırmak canlı ve hızlı geçen gerçek bir tartışmada çok yorum yapan aktif kullanıcıları bile kesintiye uğratabilir.', sensitive: true),
  ConfigField(key: 'moderation.concentration_distinct_max', type: 'int', doc: ConfigDoc.server, group: 'moderation', label: 'Yoğunlaşma tespiti — maksimum farklı kaynak', description: 'Yukarıdaki pencere dolduğunda, o pencere içindeki etkileşimlerin en fazla kaç farklı kişiden gelmesi durumunda \'yoğunlaşma\' (aynı birkaç kişinin sürekli birbirini beğenmesi) olarak işaretleneceğini belirler. Penceredeki farklı kişi sayısı bu değerin üzerindeyse hesap zaten çeşitli bir kitleden etkileşim alıyor demektir ve ceza uygulanmaz.', impact: 'Değeri düşürmek (ör. 3\'ten 1-2\'ye) küçük ama gerçek arkadaş gruplarını da \'yoğunlaşma\' diye cezalandırma riskini artırır; yükseltmek daha büyük organize gruplaşmaların tespit edilmeden kredi kazanmasına izin verir.', sensitive: true, min: 1, max: 50),
  ConfigField(key: 'moderation.concentration_downweight', type: 'double', doc: ConfigDoc.server, group: 'moderation', label: 'Yoğunlaşma ağırlık cezası', description: '\'Yoğunlaşma\' olarak işaretlenen bir etkileşimin, alıcının kredi eşiğine katkısının hangi katsayıyla azaltılacağını belirler — aynı mantığı karşılıklılık cezasıyla paylaşır, ancak ayrı bir tespit mekanizması (dar çevre) için çalışır. 1.0 cezasız, 0 ise o etkileşimin hiç sayılmaması anlamına gelir.', impact: 'Değeri 1\'e yaklaştırmak yoğunlaşma cezasını etkisizleştirip organize grupların neredeyse tam puanla kredi kazanmasına izin verir; 0\'a yaklaştırmak cezayı ağırlaştırıp küçük ama gerçek arkadaş topluluklarının da kredisini ciddi biçimde azaltabilir.', sensitive: true, min: 0, max: 1),
  ConfigField(key: 'moderation.concentration_window', type: 'int', doc: ConfigDoc.server, group: 'moderation', label: 'Yoğunlaşma tespiti — pencere', description: 'Bir kullanıcının aldığı etkileşimlerin ne kadar \'çeşitli\' bir kitleden geldiğinin değerlendirilmesi için, alıcı bazında son kaç etkileşim olayının izleneceğini belirler. Bu pencere dolmadan (yeterli veri birikmeden) hiçbir hesap \'dar bir çevreden etkileşim alıyor\' diye cezalandırılmaz.', impact: 'Değeri düşürmek yeni veya az etkileşimli hesapları erken ve yanlışlıkla \'dar çevre\' diye işaretleme riskini artırır; yükseltmek gerçek bir dar-çevre örüntüsünün fark edilmesini geciktirir.', min: 1, max: 200),
  ConfigField(key: 'moderation.duplicate_recent_window', type: 'int', doc: ConfigDoc.server, group: 'moderation', label: 'Yinelenen içerik karşılaştırma penceresi', description: 'Yeni paylaşılan bir içeriğin \'kopya\' olup olmadığı kontrol edilirken, yazarın kendi son kaç gönderi/yorum ya da grup mesajıyla karşılaştırılacağını belirler. Pencere büyüdükçe daha eski içerikler de karşılaştırmaya dahil olur (daha sıkı kontrol, biraz daha fazla okuma maliyeti); küçüldükçe yalnızca çok yakın zamandaki içerikle kıyaslanır.', impact: 'Değeri çok düşürmek eski bir içeriğin uzun süre sonra tekrar paylaşılmasını kopya olarak yakalayamaz hale getirir; çok yükseltmek her kontrolde ek okuma maliyeti getirir ve pratik faydası sınırlı kalır.', min: 1, max: 200),
  ConfigField(key: 'moderation.duplicate_similarity_threshold', type: 'double', doc: ConfigDoc.server, group: 'moderation', label: 'Yinelenen içerik benzerlik eşiği', description: 'Bir kullanıcının yeni paylaştığı bir gönderi, yorum veya grup mesajının kendi önceki içerikleriyle ne kadar örtüştüğünde \'neredeyse aynı içerik\' sayılıp krediden hariç tutulacağını belirleyen benzerlik eşiğidir (kelime örtüşmesine dayalı bir hesap; 1.0 birebir aynı metin demektir). Karşılaştırma yalnızca kullanıcının kendi geçmiş içerikleriyle yapılır, başka kullanıcılarla kıyaslanmaz — yani intihal denetimi değil, aynı içeriği tekrar tekrar paylaşarak kredi biriktirmeye karşı bir kontroldür. Eşik aşıldığında içerik krediye uygunluğunu kaybeder ve yazarın hesabına bir şüphe bayrağı eklenir.', impact: 'Eşiği düşürmek gerçekten farklı ama temaca benzer içerikleri de yanlışlıkla \'kopya\' sayıp cezalandırma riskini artırır; yükseltmek ise gerçek kopyala-yapıştır spam\'in tespit edilmeden kredi kazanmasına izin verir.', sensitive: true, min: 0.5, max: 1),
  ConfigField(key: 'moderation.follow_rate_limit', type: 'object', doc: ConfigDoc.server, group: 'moderation', label: 'Takip etme hız sınırı', description: 'Bir kullanıcının 10 dakika içinde en fazla kaç kişiyi takip edebileceğini belirler; varsayılan ayar 10 dakikada 50 takiptir ve aşıldığında 15 dakika boyunca yeni takip işlemi yapılamaz. Önerilen hesapları gezip art arda birçok kişiyi takip etmek gerçek ve yaygın bir davranış olduğundan, bu sınır diğer limitlerden bilerek daha yüksek tutulmuştur.', impact: 'Gevşetmek bir hesabın kitlesel/otomatik takip yoluyla taciz veya sahte-takipçi şişirmesi yapmasına izin verir; sıkılaştırmak yeni bir kullanıcının önerilen hesapları gezerken doğal olarak birçok kişiyi takip etmesini engelleyebilir.', sensitive: true),
  ConfigField(key: 'moderation.group_create_rate_limit', type: 'object', doc: ConfigDoc.server, group: 'moderation', label: 'Grup oluşturma hız sınırı', description: 'Bir kullanıcının 1 saat içinde en fazla kaç topluluk grubu oluşturabileceğini belirler; varsayılan ayar 1 saatte 5 gruptur ve aşıldığında 1 saat boyunca yeni grup oluşturulamaz. Normal kullanımda grup oluşturma bir kullanıcının hesabı boyunca birkaç kez yapılan nadir bir eylem olduğundan, varsayılan zaten cömerttir.', impact: 'Gevşetmek toplu sahte/spam grup oluşturmayı kolaylaştırır; sıkılaştırmak normal kullanımı nadiren etkiler ama aşırı düşürülürse meşru bir topluluk kurucusunu da engelleyebilir.', sensitive: true),
  ConfigField(key: 'moderation.message_min_text_length', type: 'int', doc: ConfigDoc.server, group: 'moderation', label: 'Mesaj minimum metin uzunluğu', description: 'Bir grup sohbetindeki mesajın, gönderenin haftalık \'grup katkısı\' puanına sayılabilmesi için gereken minimum metin uzunluğunu belirler; ekli dosya/görsel varsa metin şartı aranmaz. Bu ayar birebir (kişiye özel) sohbetleri veya mesajlaşmanın kendisini hiçbir şekilde etkilemez, yalnızca grup içi haftalık katkı/liderlik hesaplamasını etkiler.', impact: 'Düşürmek anlamsız/tek kelimelik mesajların da haftalık katkı puanına sayılmasına yol açar; yükseltmek kısa ama gerçek mesajlarla katkı sağlayan aktif üyelerin katkısının sayılmamasına neden olur.', min: 0, max: 500),
  ConfigField(key: 'moderation.message_rate_limit', type: 'object', doc: ConfigDoc.server, group: 'moderation', label: 'Sohbet mesajı hız sınırı', description: 'Bir kullanıcının 1 dakika içinde en fazla kaç sohbet mesajı gönderebileceğini belirler; varsayılan ayar, hızlı bir gerçek sohbet temposuna göre ayarlanmış 1 dakikada 30 mesajdır. Aşıldığında kullanıcı 5 dakika boyunca mesaj gönderemez; bu kilit süresi, hızlı bir mesajlaşma patlamasının diğer eylemlere kıyasla daha olası bir senaryo olması nedeniyle kasıtlı olarak kısa tutulmuştur.', impact: 'Gevşetmek mesajlaşmanın spam veya taciz amaçlı mesaj bombardımanına açık hale gelmesine izin verir; sıkılaştırmak hızlı, doğal bir sohbet temposunu kesintiye uğratıp mesajların gecikmeli görünmesine yol açar.', sensitive: true),
  ConfigField(key: 'moderation.min_account_age_ms', type: 'int', doc: ConfigDoc.server, group: 'moderation', label: 'Minimum hesap yaşı (ms)', description: 'Bir hesabın, aldığı etkileşimler karşılığında bonus AI kredisi kazanmaya başlayabilmesi için en az ne kadar süredir açık olması gerektiğini milisaniye cinsinden belirler; varsayılan 259.200.000 ms, yani 3 gündür. Bu, e-posta doğrulaması şartıyla birlikte çalışan bir hesap-yaşı kapısıdır — hesap bu yaştan gençse, aldığı etkileşim ne kadar organik olursa olsun hiçbir kredi kazandırmaz. Değer milisaniye cinsinden girilir (1 gün = 86.400.000 ms, 7 gün = 604.800.000 ms).', impact: 'Süreyi kısaltmak yeni açılan, olası bot/tek kullanımlık hesapların daha hızlı kredi kazanmaya başlamasına izin vererek kötüye kullanım riskini artırır; süreyi çok uzatmak gerçek yeni kullanıcıların ilk günlerde/haftalarda hak ettikleri krediyi kazanamamasına yol açar.', sensitive: true, min: 0, max: 2592000000),
  ConfigField(key: 'moderation.post_min_text_length', type: 'int', doc: ConfigDoc.server, group: 'moderation', label: 'Gönderi minimum metin uzunluğu', description: 'Bir gönderinin, aldığı beğeni/tepkiler karşılığında yazarına bonus AI kredisi kazandırabilmesi için içermesi gereken minimum metin uzunluğunu belirler; görselli gönderilerde metin şartı aranmaz, görsel tek başına yeterli sayılır. Bu eşik gönderi paylaşımını engellemez — kısa bir gönderi yine yayınlanır, sadece yazarına hiçbir zaman kredi kazandırmaz.', impact: 'Düşürmek düşük kaliteli/az içerikli gönderilerin de kredi kazanmasına yol açar; yükseltmek kısa ama gerçek paylaşım yapan kullanıcıların hak ettikleri krediyi kazanamamasına neden olur.', min: 0, max: 500),
  ConfigField(key: 'moderation.post_rate_limit', type: 'object', doc: ConfigDoc.server, group: 'moderation', label: 'Gönderi oluşturma hız sınırı', description: 'Bir kullanıcının 10 dakika içinde en fazla kaç gönderi paylaşabileceğini belirler; varsayılan ayar 10 dakikada 20 gönderidir ve aşıldığında kullanıcı 15 dakika boyunca yeni gönderi paylaşamaz. Genel akıştaki ve salon sayfalarındaki gönderiler tek bir ortak bütçeyi paylaşır, yani kullanıcı ikisini birden kullanarak sınırı aşamaz.', impact: 'Gevşetmek metin/görsel spam akınının akışı doldurmasına izin verir; sıkılaştırmak normal bir kullanıcının saatte birkaç kez paylaşım yapmasını bile engelleyebilir.', sensitive: true),
  ConfigField(key: 'moderation.reaction_rate_limit', type: 'object', doc: ConfigDoc.server, group: 'moderation', label: 'Beğeni/tepki hız sınırı', description: 'Bir kullanıcının 5 dakika içinde en fazla kaç beğeni/tepki verebileceğini belirler; varsayılan ayar 5 dakikada 100\'dür ve gönderi tepkileri, gönderi beğenileri ile yorum beğenileri tek bir ortak bütçeyi paylaşır. Bu, gündelik en yüksek frekanslı etkileşim türü olduğu için altı yeni limit arasında en yüksek tavana sahip olanıdır; aşıldığında 10 dakika boyunca yeni tepki/beğeni verilemez.', impact: 'Gevşetmek otomatik/bot hesaplarla kitlesel beğeni-tepki şişirmesine izin verir; sıkılaştırmak akışı hızlıca gezip çok sayıda içeriği beğenen gerçek, aktif bir kullanıcıyı bile kilitleyebilir.', sensitive: true),
  ConfigField(key: 'moderation.reciprocity_downweight', type: 'double', doc: ConfigDoc.server, group: 'moderation', label: 'Karşılıklılık ağırlık cezası', description: 'Karşılıklılık örüntüsü tespit edilen bir etkileşimin, alıcının kredi eşiğine katkısının hangi katsayıyla azaltılacağını belirler; 1.0 hiç ceza uygulanmaması, 0 ise o etkileşimin krediye hiç katkı sağlamaması anlamına gelir. Varsayılan 0.2, etkileşimin normal değerinin beşte biri kadar sayılacağı anlamına gelir.', impact: 'Değeri 1\'e yaklaştırmak cezayı etkisizleştirip karşılıklı-şişirme kötüye kullanımının neredeyse tam puan kazanmasına izin verir; 0\'a yaklaştırmak cezayı ağırlaştırıp gerçek ama yoğun etkileşen arkadaş gruplarının da kredisini ciddi oranda düşürebilir.', sensitive: true, min: 0, max: 1),
  ConfigField(key: 'moderation.reciprocity_min_pair_sample', type: 'int', doc: ConfigDoc.server, group: 'moderation', label: 'Karşılıklılık eşiği — minimum örnek', description: 'İki kullanıcı arasındaki \'karşılıklılık\' (birbirine sürekli tepki/beğeni vererek karşılıklı şişirme) denetiminin devreye girmesi için bu ikili arasında önceden en az kaç etkileşim (iki yön toplamı) birikmiş olması gerektiğini belirler. Bu sayının altındaki, henüz az etkileşimi olan çiftler hiçbir zaman karşılıklılık cezası almaz; amaç, birbirine birkaç kez tepki veren gerçek arkadaşları yanlışlıkla cezalandırmamaktır.', impact: 'Eşiği düşürmek gerçek arkadaş/aile etkileşimlerinin erken safhada \'şüpheli\' sayılıp kredi ağırlığının düşürülmesi riskini artırır; yükseltmek organize karşılıklı-tepki kötüye kullanımının daha uzun süre fark edilmemesine yol açar.', sensitive: true, min: 1, max: 100),
  ConfigField(key: 'moderation.reciprocity_ratio_threshold', type: 'double', doc: ConfigDoc.server, group: 'moderation', label: 'Karşılıklılık oran eşiği', description: 'Yeterli örnek biriken bir kullanıcı ikilisinde, etkileşimin iki yön arasında ne kadar dengeli dağıldığında karşılıklılık cezasının uygulanacağını belirleyen orandır (küçük yön / büyük yön). Varsayılan 0.5, bir yöndeki etkileşimin diğer yönün en az yarısı kadar olması durumunda cezayı tetikler; oranı 1\'e yaklaştırmak yalnızca neredeyse birebir eşit karşılıklı etkileşimi cezalandırır.', impact: 'Eşiği düşürmek (0\'a yaklaştırmak) daha dengesiz, doğal etkileşim örüntülerini de cezalandırmaya başlayıp gerçek kullanıcıları etkiler; yükseltmek (1\'e yaklaştırmak) yalnızca en bariz şişirme örüntülerini yakalar ve daha hafif kötüye kullanımın gözden kaçmasına yol açar.', sensitive: true, min: 0, max: 1),
  ConfigField(key: 'moderation.report_rate_limit', type: 'object', doc: ConfigDoc.server, group: 'moderation', label: 'Rapor gönderme hız sınırı', description: 'Bir kullanıcının 10 dakikalık bir pencere içinde en fazla kaç adet gönderi/kullanıcı/grup raporu oluşturabileceğini belirler; varsayılan ayar 10 dakikada 8 rapordur ve bu aşıldığında kullanıcı 15 dakika boyunca yeni rapor oluşturamaz hale kilitlenir. Amaç, art arda birkaç kötü paylaşımı raporlayan gerçek bir kullanıcıyı değil, birini susturmak için toplu rapor yağdıran kötüye kullanımı sınırlamaktır.', impact: 'Pencereyi/sayıyı gevşetmek toplu raporlama yoluyla birini haksız yere susturma riskini artırır; sıkılaştırmak gerçekten birden fazla kötü içerikle karşılaşan bir kullanıcının raporlama yapamaz hale gelmesine yol açar.', sensitive: true),
  ConfigField(key: 'ops_cron.admin_stats_rollup_schedule', type: 'string', doc: ConfigDoc.server, group: 'ops_cron', label: 'Admin istatistik özeti -- zamanlama (cron)', description: 'Bir önceki günün kullanıcı/abonelik/topluluk/salon/koç/moderasyon/sistem metriklerini admin_stats/day_YYYY-MM-DD ve admin_stats/global\'e yazan görevin ne zaman çalıştığını temsil eder (cron sözdizimi -- varsayılan \'0 2 * * *\' her gün UTC 02:00 anlamına gelir, bir önceki günün tamamen kapanmış olmasını beklemek için). Bu alan bugün hiçbir zamanlanmış görev tarafından okunmuyor -- Google Cloud Scheduler zamanlamaları fonksiyon dağıtımı (deploy) sırasında sabitlenir ve çalışan bir fonksiyonun kendi tetiklenme sıklığını Firestore\'dan okuyup değiştirmesi mümkün değildir. Bu alan, ileride ilgili göreve kendi içinde bir \'yeterince zaman geçti mi\' kontrolü eklenip zamanlamanın fiilen buradan okunması durumunda kullanılacak zemin olarak eklenmiştir; bugün değiştirmenin gözlemlenebilir hiçbir etkisi yoktur.', impact: 'Bu alanın şu anda hiçbir etkisi yok.'),
  ConfigField(key: 'ops_cron.broadcast_drain_period_min', type: 'int', doc: ConfigDoc.server, group: 'ops_cron', label: 'Zamanlanmış yayın gönderimi -- çalıştırma sıklığı (dk)', description: 'Zamanı gelmiş (status: scheduled) yayınları (broadcast) tarayıp gönderen görevin ne sıklıkla (dakika) çalıştığını temsil eder -- bu değer, zamanlanmış bir yayının gerçek gönderim anıyla planlanan saati arasındaki en kötü durum gecikmesini belirler. Bu alan bugün hiçbir zamanlanmış görev tarafından okunmuyor -- Google Cloud Scheduler zamanlamaları fonksiyon dağıtımı (deploy) sırasında sabitlenir ve çalışan bir fonksiyonun kendi tetiklenme sıklığını Firestore\'dan okuyup değiştirmesi mümkün değildir. Bu alan, ileride ilgili göreve kendi içinde bir \'yeterince zaman geçti mi\' kontrolü eklenip zamanlamanın fiilen buradan okunması durumunda kullanılacak zemin olarak eklenmiştir; bugün değiştirmenin gözlemlenebilir hiçbir etkisi yoktur.', impact: 'Bu alanın şu anda hiçbir etkisi yok.', min: 1, max: 60),
  ConfigField(key: 'ops_cron.group_activity_score_period_min', type: 'int', doc: ConfigDoc.server, group: 'ops_cron', label: 'Grup aktivite skoru -- çalıştırma sıklığı (dk)', description: 'Keşfet ekranındaki \'en aktif gruplar\' skorunu yeniden hesaplayan görevin ne sıklıkla (dakika) çalıştığını temsil eder. Bu alan bugün hiçbir zamanlanmış görev tarafından okunmuyor -- Google Cloud Scheduler zamanlamaları fonksiyon dağıtımı (deploy) sırasında sabitlenir ve çalışan bir fonksiyonun kendi tetiklenme sıklığını Firestore\'dan okuyup değiştirmesi mümkün değildir. Bu alan, ileride ilgili göreve kendi içinde bir \'yeterince zaman geçti mi\' kontrolü eklenip zamanlamanın fiilen buradan okunması durumunda kullanılacak zemin olarak eklenmiştir; bugün değiştirmenin gözlemlenebilir hiçbir etkisi yoktur.', impact: 'Bu alanın şu anda hiçbir etkisi yok.', min: 1, max: 1440),
  ConfigField(key: 'ops_cron.gym_wars_end_check_period_min', type: 'int', doc: ConfigDoc.server, group: 'ops_cron', label: 'Salon savaşı bitiş kontrolü -- çalıştırma sıklığı (dk)', description: 'Süresi dolmuş salon savaşlarını (gym wars) kapatıp kazananı belirleyen görevin ne sıklıkla (dakika) çalıştığını temsil eder -- bu değer, bir savaşın bitiş anıyla sonucun fiilen işlenmesi arasındaki en kötü durum gecikmesini belirler. Bu alan bugün hiçbir zamanlanmış görev tarafından okunmuyor -- Google Cloud Scheduler zamanlamaları fonksiyon dağıtımı (deploy) sırasında sabitlenir ve çalışan bir fonksiyonun kendi tetiklenme sıklığını Firestore\'dan okuyup değiştirmesi mümkün değildir. Bu alan, ileride ilgili göreve kendi içinde bir \'yeterince zaman geçti mi\' kontrolü eklenip zamanlamanın fiilen buradan okunması durumunda kullanılacak zemin olarak eklenmiştir; bugün değiştirmenin gözlemlenebilir hiçbir etkisi yoktur.', impact: 'Bu alanın şu anda hiçbir etkisi yok.', min: 1, max: 1440),
  ConfigField(key: 'ops_cron.live_contribution_leaderboard_period_min', type: 'int', doc: ConfigDoc.server, group: 'ops_cron', label: 'Canlı katkı panosu -- çalıştırma sıklığı (dk)', description: 'Grup içindeki \'şu an kim önde\' canlı katkı panosunu yeniden hesaplayan görevin ne sıklıkla (dakika) çalıştığını temsil eder. Bu alan bugün hiçbir zamanlanmış görev tarafından okunmuyor -- Google Cloud Scheduler zamanlamaları fonksiyon dağıtımı (deploy) sırasında sabitlenir ve çalışan bir fonksiyonun kendi tetiklenme sıklığını Firestore\'dan okuyup değiştirmesi mümkün değildir. Bu alan, ileride ilgili göreve kendi içinde bir \'yeterince zaman geçti mi\' kontrolü eklenip zamanlamanın fiilen buradan okunması durumunda kullanılacak zemin olarak eklenmiştir; bugün değiştirmenin gözlemlenebilir hiçbir etkisi yoktur.', impact: 'Bu alanın şu anda hiçbir etkisi yok.', min: 1, max: 1440),
  ConfigField(key: 'ops_cron.plan_offer_expiry_sweep_period_min', type: 'int', doc: ConfigDoc.server, group: 'ops_cron', label: 'Plan teklifi süre dolumu -- çalıştırma sıklığı (dk)', description: 'Süresi dolmuş plan tekliflerini (paylaşılan beslenme planı şablonları) \'süresi doldu\' olarak işaretleyen temizlik görevinin ne sıklıkla (dakika) çalıştığını temsil eder. Bu alan bugün hiçbir zamanlanmış görev tarafından okunmuyor -- Google Cloud Scheduler zamanlamaları fonksiyon dağıtımı (deploy) sırasında sabitlenir ve çalışan bir fonksiyonun kendi tetiklenme sıklığını Firestore\'dan okuyup değiştirmesi mümkün değildir. Bu alan, ileride ilgili göreve kendi içinde bir \'yeterince zaman geçti mi\' kontrolü eklenip zamanlamanın fiilen buradan okunması durumunda kullanılacak zemin olarak eklenmiştir; bugün değiştirmenin gözlemlenebilir hiçbir etkisi yoktur.', impact: 'Bu alanın şu anda hiçbir etkisi yok.', min: 1, max: 1440),
  ConfigField(key: 'ops_cron.presence_stale_sweep_period_min', type: 'int', doc: ConfigDoc.server, group: 'ops_cron', label: 'Eski oturum temizliği (presence) -- çalıştırma sıklığı (dk)', description: 'Süresi dolmuş \'salonda görünen\' oturumları kapatan temizlik görevinin ne sıklıkla (dakika) çalıştığını temsil eder. Bu alan bugün hiçbir zamanlanmış görev tarafından okunmuyor -- Google Cloud Scheduler zamanlamaları fonksiyon dağıtımı (deploy) sırasında sabitlenir ve çalışan bir fonksiyonun kendi tetiklenme sıklığını Firestore\'dan okuyup değiştirmesi mümkün değildir. Bu alan, ileride ilgili göreve kendi içinde bir \'yeterince zaman geçti mi\' kontrolü eklenip zamanlamanın fiilen buradan okunması durumunda kullanılacak zemin olarak eklenmiştir; bugün değiştirmenin gözlemlenebilir hiçbir etkisi yoktur.', impact: 'Bu alanın şu anda hiçbir etkisi yok.', min: 1, max: 1440),
  ConfigField(key: 'ops_cron.streak_at_risk_notifier_schedule', type: 'string', doc: ConfigDoc.server, group: 'ops_cron', label: '\'Serin tehlikede\' bildirimi -- zamanlama (cron)', description: 'Bugün henüz yemek kaydı yapmamış kullanıcılara \'serini kaybetme\' hatırlatma bildirimi gönderen görevin ne zaman çalıştığını temsil eder (cron sözdizimi: dakika saat gün ay haftanın-günü -- varsayılan \'0 17 * * *\' her gün saat 17:00 anlamına gelir). Bu alan bugün hiçbir zamanlanmış görev tarafından okunmuyor -- Google Cloud Scheduler zamanlamaları fonksiyon dağıtımı (deploy) sırasında sabitlenir ve çalışan bir fonksiyonun kendi tetiklenme sıklığını Firestore\'dan okuyup değiştirmesi mümkün değildir. Bu alan, ileride ilgili göreve kendi içinde bir \'yeterince zaman geçti mi\' kontrolü eklenip zamanlamanın fiilen buradan okunması durumunda kullanılacak zemin olarak eklenmiştir; bugün değiştirmenin gözlemlenebilir hiçbir etkisi yoktur.', impact: 'Bu alanın şu anda hiçbir etkisi yok.'),
  ConfigField(key: 'ops_cron.summary_stale_sweep_period_min', type: 'int', doc: ConfigDoc.server, group: 'ops_cron', label: 'Eski özet temizliği -- çalıştırma sıklığı (dk)', description: 'Süresi dolmuş AI ilerleme özetlerini silen temizlik görevinin ne sıklıkla (dakika) çalıştığını temsil eder. Bu alan bugün hiçbir zamanlanmış görev tarafından okunmuyor -- Google Cloud Scheduler zamanlamaları fonksiyon dağıtımı (deploy) sırasında sabitlenir ve çalışan bir fonksiyonun kendi tetiklenme sıklığını Firestore\'dan okuyup değiştirmesi mümkün değildir. Bu alan, ileride ilgili göreve kendi içinde bir \'yeterince zaman geçti mi\' kontrolü eklenip zamanlamanın fiilen buradan okunması durumunda kullanılacak zemin olarak eklenmiştir; bugün değiştirmenin gözlemlenebilir hiçbir etkisi yoktur.', impact: 'Bu alanın şu anda hiçbir etkisi yok.', min: 1, max: 1440),
  ConfigField(key: 'ops_cron.weekly_group_reward_period_hours', type: 'int', doc: ConfigDoc.server, group: 'ops_cron', label: 'Haftalık grup ödülü -- çalıştırma sıklığı (saat)', description: 'Haftalık grup katkı ödülünü (AI kredisi dağıtımı) hesaplayan görevin ne sıklıkla (saat) çalıştığını temsil eder; görevin kendisi yalnızca hafta gerçekten kapandığında gerçek bir ödül dağıtır, bu değer sadece kontrol sıklığıdır. Bu alan bugün hiçbir zamanlanmış görev tarafından okunmuyor -- Google Cloud Scheduler zamanlamaları fonksiyon dağıtımı (deploy) sırasında sabitlenir ve çalışan bir fonksiyonun kendi tetiklenme sıklığını Firestore\'dan okuyup değiştirmesi mümkün değildir. Bu alan, ileride ilgili göreve kendi içinde bir \'yeterince zaman geçti mi\' kontrolü eklenip zamanlamanın fiilen buradan okunması durumunda kullanılacak zemin olarak eklenmiştir; bugün değiştirmenin gözlemlenebilir hiçbir etkisi yoktur.', impact: 'Bu alanın şu anda hiçbir etkisi yok.', min: 1, max: 168),
  ConfigField(key: 'ops_cron.weekly_plan_ready_notifier_schedule', type: 'string', doc: ConfigDoc.server, group: 'ops_cron', label: 'Haftalık plan hazır bildirimi -- zamanlama (cron)', description: 'Yeni haftalık yemek planı hazır olan kullanıcılara bildirim gönderen görevin ne zaman çalıştığını temsil eder (cron sözdizimi -- varsayılan \'0 7 * * 1\' her Pazartesi saat 07:00 anlamına gelir). Bu alan bugün hiçbir zamanlanmış görev tarafından okunmuyor -- Google Cloud Scheduler zamanlamaları fonksiyon dağıtımı (deploy) sırasında sabitlenir ve çalışan bir fonksiyonun kendi tetiklenme sıklığını Firestore\'dan okuyup değiştirmesi mümkün değildir. Bu alan, ileride ilgili göreve kendi içinde bir \'yeterince zaman geçti mi\' kontrolü eklenip zamanlamanın fiilen buradan okunması durumunda kullanılacak zemin olarak eklenmiştir; bugün değiştirmenin gözlemlenebilir hiçbir etkisi yoktur.', impact: 'Bu alanın şu anda hiçbir etkisi yok.'),
  ConfigField(key: 'presence.max_friends_fanout', type: 'int', doc: ConfigDoc.server, group: 'ops_caps', label: 'Arkadaş bildirimi fan-out limiti', description: 'Bir kullanıcı spor salonuna geldiğinde, \'arkadaşın salonda\' bildirimi gönderilip gönderilmeyeceğini kontrol etmek amacıyla o kullanıcının arkadaş listesinden en fazla kaç kişinin okunacağını belirleyen teknik bir üst sınırdır; esas olarak performans ve maliyet amaçlı bir kapasite sınırıdır, kullanıcıya bir ayar olarak gösterilmez. Uygulamada arkadaş sayısına ayrı bir üst sınır bulunmadığından, çok sayıda arkadaşı olan bir kullanıcı için bu değer, sınırın üzerinde kalan arkadaşların bu bildirimden hiç yararlanamaması anlamına da gelebilir.', impact: 'Çok düşük bir değer, çok arkadaşı olan kullanıcılarda bazı arkadaşların \'salonda\' bildirimini hiç alamamasına yol açar; çok yüksek bir değer her salon girişinde okunacak veri miktarını ve maliyeti artırır.', min: 10, max: 5000),
  ConfigField(key: 'presence.notify_log_ttl_days', type: 'int', doc: ConfigDoc.server, group: 'presence', label: 'Bildirim log TTL (gün)', description: '\'Arkadaşın salonda\' bildiriminin aynı gün içinde aynı kişi için tekrar gönderilmediğini hatırlamak amacıyla tutulan küçük kayıtların kaç gün saklanacağını belirler. Aynı arkadaş aynı güne birden fazla kez gelse bile günde en fazla bir bildirim gitmesi kuralı takvim gününe dayanır ve bu değerden bağımsız işler; bu alan yalnızca söz konusu kayıtların saklama/temizlik süresini ayarlar.', impact: 'Değerin değiştirilmesi bildirim sıklığını etkilemez, yalnızca tekrar-önleme kayıtlarının veritabanında ne kadar süre tutulacağını değiştirir.', min: 1, max: 30),
  ConfigField(key: 'presence.presence_ttl_ms', type: 'int', doc: ConfigDoc.server, group: 'presence', label: 'Oturum geçerlilik süresi (ms)', description: 'Bir kullanıcı için açılan \'şu an salonda\' oturumunun, gerçek bir çıkış olayı hiç gelmese bile en fazla ne kadar süre (milisaniye) açık kalabileceğini belirleyen bir güvenlik sınırıdır — uygulamanın veya telefonun beklenmedik şekilde kapanması gibi durumlarda oturumun sonsuza dek \'açık\' görünmesini engeller. Bu süre dolduğunda arka plandaki temizlik işi oturumu otomatik kapatır, salonun canlı doluluk sayısını düşürür ve normal bir çıkış gibi işler. Kısacası bir salon ziyaretinin en fazla bu kadar sürebileceği varsayılır.', impact: 'Değerin çok yüksek tutulması, salonu çoktan terk etmiş kullanıcıların uzun süre \'hâlâ salonda\' görünüp canlı doluluk sayısını yanlış göstermesine yol açar; çok düşük tutulması gerçekten uzun süren ziyaretlerin erken ve yanlışlıkla kapatılmasına neden olabilir.', min: 600000, max: 86400000),
  ConfigField(key: 'presence.quiet_hours_end', type: 'int', doc: ConfigDoc.server, group: 'presence', label: 'Sessiz saat bitişi (yerel saat)', description: '\'Arkadaşın salonda\' bildirimlerinin gönderilebileceği günlük saat aralığının bitişidir (yerel saat, Türkiye için UTC+3). Bu saatten sonra gerçekleşen bir salon girişi için bildirim hiç gönderilmez; daha sonraya ertelenmez, tamamen atlanır. presence.quiet_hours_start ile birlikte gece sessiz saatlerini tanımlar.', impact: 'Bu saati geriye çekmek akşam saatlerindeki gerçek salon girişlerinin bildirimsiz kalmasına yol açar, ileri çekmek ise gece geç saatlere kadar bildirim gönderilmesine izin verir.', min: 0, max: 23),
  ConfigField(key: 'presence.quiet_hours_start', type: 'int', doc: ConfigDoc.server, group: 'presence', label: 'Sessiz saat başlangıcı (yerel saat)', description: '\'Arkadaşın salonda\' bildirimlerinin gönderilebileceği günlük saat aralığının başlangıcıdır (yerel saat, Türkiye için UTC+3). Bu saatten önce gerçekleşen bir salon girişi için bildirim hiç gönderilmez; daha sonraya ertelenmez, tamamen atlanır. presence.quiet_hours_end ile birlikte gece saatlerinde kullanıcıları rahatsız etmemeyi amaçlar.', impact: 'Bu saati ileri çekmek sabah erken saatlerdeki gerçek salon girişlerinin bildirimsiz kalmasına yol açar, geriye çekmek ise gece geç saatlerde de bildirim gönderilmesine izin verir.', min: 0, max: 23),
  ConfigField(key: 'presence.rate_limit_reentry_ms', type: 'int', doc: ConfigDoc.server, group: 'presence', label: 'Yeniden giriş hız sınırı (ms)', description: 'Bir kullanıcı bir spor salonundan çıktıktan sonra, aynı salon için yeni bir \'içeride\' oturumunun açılabilmesi için beklenmesi gereken minimum süredir (milisaniye). GPS sinyalinin salon sınırında kısa süreli oynayıp (flicker) art arda sahte giriş-çıkış olayları tetiklemesini engellemek için kullanılır. Bu süre dolmadan gelen yeni bir giriş denemesi reddedilir ve yeni bir oturum ya da check-in kaydı oluşmaz.', impact: 'Değerin çok yüksek tutulması, kısa süre içinde salona gerçekten tekrar giren bir kullanıcının yeni oturumunun kabul edilmemesine yol açar; çok düşük tutulması GPS oynamalarının tekrar tekrar sahte giriş-çıkış olarak kaydedilmesine izin verir.', min: 60000, max: 3600000),
  ConfigField(key: 'presence.stale_sweep_limit', type: 'int', doc: ConfigDoc.server, group: 'ops_caps', label: 'Eski oturum temizleme limiti', description: 'Süresi dolmuş \'salonda görünen\' oturumları kapatan ve her 15 dakikada bir çalışan arka plan temizlik işinin, tek seferde işleyeceği maksimum kayıt sayısıdır. Saf bir işlem verimliliği/performans ayarıdır; kullanıcıya doğrudan görünmez ve herhangi bir iş kuralını değiştirmez.', impact: 'Çok düşük bir değer, aynı anda çok sayıda süresi dolmuş oturum birikirse hepsinin tek çalıştırmada temizlenememesine yol açar; çok yüksek bir değer tek çalıştırmanın süresini ve maliyetini artırır.', min: 10, max: 5000),
  ConfigField(key: 'presence.timestamp_skew_ms', type: 'int', doc: ConfigDoc.server, group: 'presence', label: 'İzin verilen saat sapması (ms)', description: 'Bir kullanıcının spor salonu giriş/çıkış (geofence) olayı gönderirken cihaz saatinin sunucu saatinden en fazla kaç milisaniye sapabileceğini belirler. Bu sınırı aşan bir istek — cihaz saati yanlış ayarlanmış olsun ya da kasıtlı sahte bir zaman damgası gönderilsin — sunucu tarafından tamamen reddedilir. Salon check-in ve oturum kayıtlarının gerçek zamana dayandığından emin olmak için kullanılan bir güvenlik kontrolüdür.', impact: 'Değerin çok düşük tutulması, saati hafifçe yanlış olan dürüst kullanıcıların salon giriş/çıkış işlemlerinin reddedilmesine yol açabilir; çok yüksek tutulması sahte veya oynanmış zaman damgalarına karşı korumayı zayıflatır.', sensitive: true, min: 10000, max: 3600000),
  ConfigField(key: 'privacy.k_anonymity_threshold', type: 'int', doc: ConfigDoc.client, group: 'privacy', label: 'K-anonimlik eşiği (salon analitiği)', description: 'Bir salonun toplu analiz kartında (üyelerin ortalama check-in sıklığı/serisi gibi) bir sayı gösterilebilmesi için, ilerleme paylaşımına onay vermiş en az kaç üye olması gerektiğini belirler. Bu eşiğin altındaki gruplarda sunucu ortalamayı hiç hesaplamaz, yalnızca \'gösterilemez\' bilgisini döner — küçük bir grupta tek bir üyenin verisinin ortalama üzerinden tahmin edilebilmesi böylece engellenir. Bu kontrol sunucu (Cloud Function) tarafında uygulanır; yalnızca ekranda sayı gösterilip gösterilmeyeceğine karar veren bir arayüz kuralı değildir.', impact: 'Eşiği düşürmek daha küçük gruplarda da ortalamanın gösterilmesini sağlar ama bir üyenin verisinin diğerlerinden ayırt edilebilme riskini artırır, yükseltmek gizliliği güçlendirir ama küçük salonların bu kartı hiç görememesine yol açar.', sensitive: true, min: 2, max: 50),
  ConfigField(key: 'purchases.products', type: 'map<string,object>', doc: ConfigDoc.server, group: 'economy', label: 'Ürün kataloğu', description: 'Uygulama içi satın almalarda her mağaza ürün kimliğinin (productId) kullanıcıya tam olarak neyi kazandıracağını tanımlayan kataloğu belirler: abonelik ürünlerinde kademe (tier) ve süre (days, gün), tüketilebilir ürünlerde ise kaç bonus AI kredisi (bonusCredits) verileceği. Bu katalog yalnızca Apple/Google mağazası bir satın almayı onayladıktan sonra sunucunun \'bu ürün kullanıcıya ne veriyor\' kararını vermesinde kullanılır; hangi ürünlerin mağazada satışa sunulacağını belirlemez, çünkü uygulamanın satın alma ekranı ayrı ve bu ayardan bağımsız bir ürün listesi kullanır. Buraya yeni bir ürün eklemek, mağaza konsollarında ve uygulama tarafında ayrıca tanımlanmadıkça o ürünü satışa çıkarmaz.', impact: 'Var olan bir ürün kimliğini silmek veya yanlış yazmak, o ürünü zaten satın almış gerçek kullanıcılara hakkının (premium veya kredi) tanımlanmamasına yol açar; days/bonusCredits değerlerini yanlış girmek ise kullanıcıya gereğinden az ya da fazla hak verilmesine neden olur.', sensitive: true),
  ConfigField(key: 'rollout.coach', type: 'int', doc: ConfigDoc.critical, group: 'rollout', label: 'Koç — kademeli açılım %', description: 'Koç ekosisteminin kullanıcıların yüzde kaçına açık olacağını belirler; rollout.gym ile aynı sabit-gruplama mekanizmasını kullanır. Her kullanıcı kimliğine göre sabit bir gruba düşer, böylece yüzde yükseltildiğinde önceden erişimi olanlar erişimini kaybetmez. Bu yüzde yalnızca \'Koç ekosistemi\' ana anahtarı (features.coach) açıkken devreye girer. Varsayılan %100\'dür.', impact: 'Yüzdeyi düşürmek koç ekosistemini rastgele seçilmiş kullanıcılardan gizler, yükseltmek ise ek test yapılmadan daha fazla kullanıcıya birden erişim açar.', min: 0, max: 100),
  ConfigField(key: 'rollout.gym', type: 'int', doc: ConfigDoc.critical, group: 'rollout', label: 'Salon — kademeli açılım %', description: 'Salon (gym) ekosisteminin — salon panosu, check-in, salon analitiği gibi tüm giriş noktalarının — kullanıcıların yüzde kaçına açık olacağını belirler. Her kullanıcı, kimliğine göre sabit bir şekilde 0-99 arası bir gruba düşer; yüzde yükseltildiğinde önceden erişimi olanlar erişimini kaybetmez, sadece yeni kullanıcılar eklenir. Bu yüzde yalnızca \'Spor salonu ekosistemi\' ana anahtarı (features.gym) açıkken bir anlam ifade eder — o anahtar kapalıyken salon kimseye görünmez. Varsayılan %100\'dür, yani bugün herkese açıktır.', impact: 'Yüzdeyi düşürmek salon ekosistemini rastgele seçilmiş bir kullanıcı grubundan gizler (kademeli/kontrollü açılım için kullanışlıdır), yükseltmek ise ek test yapılmadan daha fazla kullanıcıya birden erişim açar.', min: 0, max: 100),
  ConfigField(key: 'rollout.programs', type: 'int', doc: ConfigDoc.critical, group: 'rollout', label: 'Programlar — kademeli açılım %', description: 'Programlar (pazar yeri) özelliğinin kullanıcıların yüzde kaçına açık olacağını belirler; rollout.gym ile aynı sabit-gruplama mekanizmasını kullanır. Bu yüzde yalnızca \'Programlar (pazar yeri)\' ana anahtarı (features.programs) açıkken bir anlam ifade eder. Varsayılan %100\'dür, yani bugün herkese açıktır.', impact: 'Yüzdeyi düşürmek pazar yerini rastgele seçilmiş kullanıcılardan gizler, yükseltmek ise ek test yapılmadan daha fazla kullanıcıya birden erişim açar.', min: 0, max: 100),
  ConfigField(key: 'rollout.squad', type: 'int', doc: ConfigDoc.critical, group: 'rollout', label: 'Squad — kademeli açılım %', description: 'Squad (Streak Squad — küçük grup halinde seri/streak takibi) özelliğinin kullanıcıların yüzde kaçına açık olacağını belirler; rollout.gym ile aynı sabit-gruplama mekanizmasını kullanır. Bu yüzde yalnızca \'Squad\' ana anahtarı (features.squad) açıkken bir anlam ifade eder. Varsayılan %100\'dür.', impact: 'Yüzdeyi düşürmek Squad özelliğini rastgele seçilmiş kullanıcılardan gizler, yükseltmek ise ek test yapılmadan daha fazla kullanıcıya birden erişim açar.', min: 0, max: 100),
  ConfigField(key: 'summaries.gen_rate_max_in_window', type: 'int', doc: ConfigDoc.server, group: 'ops_caps', label: 'Pencere başına maksimum özet', description: 'summaries.gen_rate_window_ms ile tanımlanan zaman penceresi içinde, bir salon sahibinin veya koçun aynı üye için en fazla kaç kez yeni bir AI ilerleme özeti üretebileceğini belirler (varsayılan: pencere başına 1). Bu sınırı aşan bir üretim isteği sunucu tarafından reddedilir; amaç aynı üye hakkında art arda AI çağrısı yapılıp gereksiz maliyet oluşmasını engellemektir.', impact: 'Değerin artırılması aynı üye için daha sık özet üretimine ve daha fazla AI maliyetine izin verir; düşürülmesi özelliğin kullanılabilirliğini kısıtlar.', min: 1, max: 10),
  ConfigField(key: 'summaries.gen_rate_window_ms', type: 'int', doc: ConfigDoc.server, group: 'ops_caps', label: 'Özet üretim hız penceresi (ms)', description: 'Bir salon sahibinin veya koçun, aynı üye için yeni bir AI destekli ilerleme özeti üretebilmeden önce beklemesi gereken zaman penceresidir (milisaniye). summaries.gen_rate_max_in_window ile birlikte, \'aynı salon sahibi/koç-üye çifti için bu pencerede en fazla kaç özet üretilebilir\' kuralını oluşturur. Özet üretimi gerçek bir AI çağrısı ve maliyeti gerektirdiğinden bu pencere doğrudan maliyet kontrolü amacı taşır.', impact: 'Pencereyi kısaltmak aynı üye için daha sık özet üretilmesine ve dolayısıyla daha fazla AI maliyetine izin verir, uzatmak ise salon sahibinin/koçun güncel bir özete erişimini geciktirir.', min: 3600000, max: 604800000),
  ConfigField(key: 'summaries.max_scope_members_scan', type: 'int', doc: ConfigDoc.server, group: 'ops_caps', label: 'Kapsam üyesi tarama limiti', description: 'Bir salon sahibinin veya koçun kapsamındaki kişilerden (salonun üyeleri ya da koçun aktif danışanları) kaç tanesinin ilerleme paylaşımına onay verip vermediğinin kontrol edileceğini sınırlayan dahili bir tarama sınırıdır. İşlem verimliliği/performans ayarıdır, kullanıcıya doğrudan görünmez; bir iş kuralı ya da kötüye kullanım koruması taşımaz.', impact: 'Çok yüksek bir değer bu kontrolün maliyetini artırır; çok düşük bir değer, çok büyük bir salon veya danışan listesinde sınırın üzerinde kalan kişilerin onay durumunun hiç kontrol edilmemesine yol açabilir.', min: 10, max: 5000),
  ConfigField(key: 'summaries.stale_sweep_limit', type: 'int', doc: ConfigDoc.server, group: 'ops_caps', label: 'Eski özet temizleme limiti', description: 'Süresi dolmuş AI ilerleme özetlerini silen ve her 60 dakikada bir çalışan arka plan temizlik işinin, tek seferde işleyeceği maksimum kayıt sayısıdır. Saf bir işlem verimliliği/performans ayarıdır, kullanıcıya doğrudan görünmez.', impact: 'Çok düşük bir değer, aynı anda çok sayıda süresi dolmuş özet birikirse hepsinin tek çalıştırmada silinememesine (temizliğin gecikmesine) yol açar; çok yüksek bir değer tek çalıştırmanın maliyetini artırır.', min: 10, max: 5000),
  ConfigField(key: 'summaries.ttl_ms', type: 'int', doc: ConfigDoc.server, group: 'ops_caps', label: 'Özet TTL (ms)', description: 'Üretilen bir AI ilerleme özetinin ne kadar süre (milisaniye) geçerli sayılıp önbellekte tutulacağını belirler; bu süre sonunda özet arka plandaki bir temizlik işi tarafından tamamen silinir. Süre dolduktan sonra aynı üye için tekrar özet görüntülenmek istenirse yeniden üretilmesi gerekir; bu da yukarıdaki hız sınırına ve yeni bir AI maliyetine tabidir.', impact: 'Süreyi uzatmak eski/güncelliğini yitirmiş bir özetin daha uzun süre gösterilmesine yol açar, kısaltmak ise özetlerin daha sık yeniden üretilmesini ve dolayısıyla daha fazla AI maliyetini gerektirir.', min: 3600000, max: 2592000000),
  ConfigField(key: 'templates.max_message_length', type: 'int', doc: ConfigDoc.server, group: 'ops_caps', label: 'Maksimum mesaj uzunluğu', description: 'Bir plan teklifiyle birlikte gönderilecek kişisel mesajın en fazla kaç karakter olabileceğini belirler. Bu sınır, teklifi gönderen kişinin ekranındaki mesaj kutusunda kullanıcının doğrudan gördüğü bir arayüz sınırı olarak ve sunucu tarafında aynı anda uygulanır; sınırı aşan metin sunucu tarafında sessizce kırpılır.', impact: 'Değerin artırılması gönderenlerin daha uzun kişisel mesaj yazabilmesini sağlar, düşürülmesi ise mevcut uzunluktaki mesajların kırpılmasına yol açabilir.', min: 10, max: 5000),
  ConfigField(key: 'templates.max_recipients_per_call', type: 'int', doc: ConfigDoc.server, group: 'ops_caps', label: 'Çağrı başına maksimum alıcı', description: 'Bir plan teklifinin tek bir gönderim işleminde en fazla kaç alıcıya birden gönderilebileceğini belirler (ör. bir salon sahibinin, koçun veya adminin toplu gönderim yaptığı durum). Bu sayıyı aşan bir gönderim denemesi sunucu tarafından reddedilir; normal salon/koç gönderimleri genelde bu sınırın çok altında kaldığından bu esasen çok geniş toplu gönderimlere (ör. admin duyurusu) karşı bir koruma katmanıdır.', impact: 'Değerin çok düşük tutulması meşru büyük toplu gönderimleri engelleyebilir veya parçalara bölmeye zorlar; çok yüksek tutulması tek bir çağrıda aşırı sayıda yazma işlemine izin vererek performans/maliyet riski oluşturur.', min: 1, max: 1000),
  ConfigField(key: 'templates.offer_ttl_days', type: 'int', doc: ConfigDoc.server, group: 'economy', label: 'Plan teklifi geçerlilik süresi (gün)', description: 'Bir salon sahibi, koç veya admin tarafından bir üyeye gönderilen plan teklifinin (paylaşılan bir beslenme planı şablonu), yanıtsız kalması hâlinde kaç gün sonra otomatik olarak süresinin dolacağını belirler. Süre dolduğunda arka plandaki bir iş teklifin durumunu \'süresi doldu\' olarak günceller ve teklif alıcının gelen kutusunda artık kabul edilebilir/aktif görünmez.', impact: 'Süreyi uzatmak yanıtsız tekliflerin daha uzun süre aktif ve kabul edilebilir kalmasını sağlar, kısaltmak ise üyelerin teklife yanıt vermesi için daha az zamanı olmasına yol açar.', min: 1, max: 90),
  ConfigField(key: 'theme.accent_color_hex', type: 'string', doc: ConfigDoc.client, group: 'theme', label: 'Aksan rengi (hex)', description: 'Uygulamanın ikincil/aksan rengi için sunucu tarafından sağlanan varsayılan değerdir. Bugün bu değeri okuyan bir kod yolu yoktur; aksan rengi hâlâ uygulama kodunda sabittir. Bu alan M7 kapsamında kurulacak uzaktan tema özelliği için zemin olarak eklenmiştir.', impact: 'Bu alanın şu anda hiçbir etkisi yok; ileride canlı hale getirildiğinde uygulamanın aksan/ikincil rengini değiştirecektir.'),
  ConfigField(key: 'theme.banner_style', type: 'enum', doc: ConfigDoc.client, group: 'theme', label: 'Duyuru şeridi görsel stili', description: 'Duyuru şeridinin (announcement.enabled açıkken gösterilen şerit) genel görsel stilini kaba/belirgin (\'bold\') ile sade/minimal (\'minimal\') arasında değiştirmesi planlanan bir alandır — hangi renk/ikon gösterileceğini belirleyen announcement.type\'tan farklıdır, bu alan şeridin kendi görsel diline (kalınlık, gölge, köşe yuvarlaklığı gibi) ilişkindir. Bugün bu değeri okuyan bir kod yolu yoktur; şerit her zaman uygulamanın kendi sabit tasarımıyla gösterilir.', impact: 'Bu alanın şu anda hiçbir etkisi yok; değiştirmek güvenlidir ama duyuru şeridinin görünümünü değiştirmez.', enumValues: <String>['bold', 'minimal']),
  ConfigField(key: 'theme.dark_mode_default', type: 'enum', doc: ConfigDoc.client, group: 'theme', label: 'Varsayılan karanlık mod tercihi', description: 'Henüz kendi tema tercihini seçmemiş bir kullanıcı için uygulamanın açık/koyu/sistem temalarından hangisiyle başlayacağını belirlemesi planlanan bir alandır. Bugün bu değeri okuyan bir kod yolu yoktur — ThemeProvider her zaman \'light\' (açık tema) ile başlar; kullanıcı kendi tercihini değiştirdiğinde bu tercih cihazında ve hesabında saklanır.', impact: 'Bu alanın şu anda hiçbir etkisi yok; ileride canlı hale getirildiğinde yalnızca HENÜZ tercih belirlememiş kullanıcıları etkileyecektir, zaten bir tema seçmiş kullanıcıları değiştirmeyecektir.', enumValues: <String>['light', 'dark', 'system']),
  ConfigField(key: 'theme.logo_url', type: 'string', doc: ConfigDoc.client, group: 'theme', label: 'Uzaktan logo URL\'i', description: 'Boş olmadığında, uygulama içinde paket içi (bundled) logo yerine bu adresten yüklenecek bir logo göstermek için kullanılması planlanan bir alandır. Bugün bu URL\'i okuyan bir ekran yoktur; uygulamanın logosu hâlâ paket içindeki sabit görsel dosyasıdır. Boş bırakıldığında (bugünkü hal) hiçbir davranış değişmez.', impact: 'Bu alanın şu anda hiçbir etkisi yok; ileride canlı hale getirildiğinde, erişilemeyen veya hatalı bir adres girmek logonun hiç yüklenememesine yol açabilir.'),
  ConfigField(key: 'theme.primary_color_hex', type: 'string', doc: ConfigDoc.client, group: 'theme', label: 'Birincil renk (hex)', description: 'Uygulamanın birincil (brand) rengi için sunucu tarafından sağlanan varsayılan değerdir. Bugün bu değeri gerçekte kullanan bir okuma yolu yoktur — birincil renk hâlâ uygulama kodunda sabit (constants.dart) ve her kullanıcı kendi tercihini ayrıca (4 hazır renkten birini seçerek) belirleyebiliyor. Bu alan, M7 kapsamında sunucudan marka rengi değiştirme özelliği kurulduğunda kullanılacak zemin olarak eklenmiştir.', impact: 'Bu alanın şu anda hiçbir etkisi yok; ileride canlı hale getirildiğinde, henüz kendi rengini seçmemiş kullanıcıların gördüğü varsayılan rengi değiştirecektir.'),
  ConfigField(key: 'version.android_store_url', type: 'string', doc: ConfigDoc.critical, group: 'version', label: 'Play Store URL', description: 'Zorunlu güncelleme ekranındaki \'Güncelle\' butonuna basıldığında açılan Google Play Store sayfasının adresidir. Yalnızca Android kullanıcıları için kullanılır ve yalnızca force_update aktifken gösterilen ekranda işlev görür. Boş bırakılırsa buton hiçbir şey yapmaz.', impact: 'Düşük risk — yanlış veya boş URL yalnızca güncelleme ekranındaki butonun yönlendirmesini bozar, kilidin kendisini etkilemez.'),
  ConfigField(key: 'version.force_update', type: 'bool', doc: ConfigDoc.critical, group: 'version', label: 'Zorunlu güncelleme', description: '\'Minimum desteklenen sürüm\' alanlarını gerçek bir zorunlu güncelleme kapısına dönüştüren ana anahtardır. Açık olduğunda ve kullanıcının yüklü sürümü ilgili platformun minimum değerinin altındaysa, kullanıcı geri tuşuyla bile kapatılamayan tam ekran bir güncelleme duvarına kilitlenir; tek çıkış yolu mağaza sayfasını açan butondur. Uygulama kendi sürüm bilgisini henüz okuyamadıysa bu kontrol o ana kadar devre dışı kalır, yani bir aksaklık durumunda kapıyı yanlışlıkla kapatmaz.', impact: 'Açmak, minimum sürümün altındaki tüm kullanıcıları anında ve uygulama içinden atlanamayacak şekilde kilitler; bu yüzden hassas alandır ve kaydetmek için onay ile gerekçe metni ister.', sensitive: true),
  ConfigField(key: 'version.ios_store_url', type: 'string', doc: ConfigDoc.critical, group: 'version', label: 'App Store URL', description: 'Zorunlu güncelleme ekranındaki \'Güncelle\' butonuna basıldığında açılan App Store sayfasının adresidir. Yalnızca iOS kullanıcıları için kullanılır ve yalnızca force_update aktifken gösterilen ekranda işlev görür. Boş bırakılırsa buton hiçbir şey yapmaz.', impact: 'Düşük risk — yanlış veya boş URL yalnızca güncelleme ekranındaki butonun yönlendirmesini bozar, kilidin kendisini etkilemez.'),
  ConfigField(key: 'version.latest_android', type: 'string', doc: ConfigDoc.critical, group: 'version', label: 'Android en güncel sürüm', description: 'Android için \'mağazadaki en güncel sürüm\' bilgisini tutar; amacı, kullanıcıya zorunlu olmayan bir \'yeni sürüm var\' hatırlatması göstermektir. Ancak uygulamada bu bilgiyi okuyup ekrana yansıtan hiçbir ekran şu anda çalışmıyor. Yani bu alan panelde düzenlenebilir olsa da, bugün itibarıyla kullanıcı tarafında hiçbir görünür sonucu yoktur.', impact: 'Bu alanın şu anda hiçbir etkisi yok; değiştirmek güvenlidir ama hiçbir şeyi değiştirmez.'),
  ConfigField(key: 'version.latest_ios', type: 'string', doc: ConfigDoc.critical, group: 'version', label: 'iOS en güncel sürüm', description: 'iOS için \'mağazadaki en güncel sürüm\' bilgisini tutar; amacı, kullanıcıya zorunlu olmayan bir \'yeni sürüm var\' hatırlatması göstermektir. Android muadili gibi, bu değeri okuyup ekrana yansıtan hiçbir ekran şu anda çalışmıyor. Bu alan panelde düzenlenebilir olsa da, bugün itibarıyla kullanıcı tarafında hiçbir görünür sonucu yoktur.', impact: 'Bu alanın şu anda hiçbir etkisi yok; değiştirmek güvenlidir ama hiçbir şeyi değiştirmez.'),
  ConfigField(key: 'version.min_supported_android', type: 'string', doc: ConfigDoc.critical, group: 'version', label: 'Android minimum desteklenen sürüm', description: 'Android için desteklenen en düşük sürümü belirtir (ör. 2.3.0). Tek başına hiçbir şey yapmaz — yalnızca \'Zorunlu güncelleme\' (version.force_update) açıkken devreye girer: kullanıcının yüklü sürümü bu değerden düşükse ve force_update açıksa, kullanıcı zorunlu güncelleme ekranına kilitlenir. \'0.0.0\' veya boş değer bu kontrolü etkisiz bırakır.', impact: 'force_update kapalıyken bu alanın hiçbir etkisi yoktur; force_update açıkken çok yüksek girilen bir değer, güncel olmayan tüm Android kullanıcılarını uygulama dışında bırakabilir.'),
  ConfigField(key: 'version.min_supported_ios', type: 'string', doc: ConfigDoc.critical, group: 'version', label: 'iOS minimum desteklenen sürüm', description: 'iOS için desteklenen en düşük sürümü belirtir (ör. 2.3.0). Yalnızca \'Zorunlu güncelleme\' (version.force_update) açıkken anlam kazanır: kullanıcının yüklü sürümü bu değerin altındaysa ve force_update açıksa, kullanıcı zorunlu güncelleme ekranına yönlendirilir. \'0.0.0\' veya boş değer bu kontrolü devre dışı bırakır.', impact: 'force_update kapalıyken etkisizdir; force_update açıkken hatalı yüksek bir değer, güncel olmayan tüm iOS kullanıcılarını uygulama dışında bırakabilir.'),
  ConfigField(key: 'version.update_message', type: 'map<string,string>', doc: ConfigDoc.critical, group: 'version', label: 'Güncelleme mesajı (en/tr)', description: 'Zorunlu güncelleme ekranında başlığın altında gösterilen açıklama metnidir (en/tr). İlgili dil için metin boş bırakılırsa, uygulamanın kendi yerleşik varsayılan güncelleme mesajı gösterilir. Bu metni yalnızca zaten force_update tarafından kilitlenmiş kullanıcılar görür.', impact: 'Düşük risk — yalnızca zorunlu güncelleme ekranındaki açıklama yazısını değiştirir, kilidin kendisini etkilemez.'),
];
